'use strict';
(() => {
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='word-choice')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('prophet','From Greek prophētēs “interpreter or spokesman,” via Latin propheta; the Greek formation refers to speaking on behalf of another.',C('prophet.s1','宗教','The prophet warned the city that the river would flood.','先知警告全城，河水将要泛滥。','prophet + reported message','可指宣告神意的人，也可引申为某领域的预言者。','本句取宗教义项：人物发出预言。'),M('The prophet forecasted that the river flood tomorrow.','The prophet forecast that the river would flood tomorrow.','在间接引语中要用完整从句；forecast 后也可直接接名词，但不能写 forecasted that ... 的此处误构。','grammar'),[Q(1,'In the sentence “She was a prophet of modern design,” what does prophet mean?','an influential advocate who anticipated a trend','a person who repairs old designs','a formal government inspector','Here prophet is metaphorical: a person whose ideas anticipate or champion a future development.','context'),Q(1,'Which collocation most naturally refers to a religious prophet?','a prophet who delivers a divine message','a prophet who files a tax return','a prophet that measures rainfall only','The core religious sense is a person believed to declare a divine message.','collocation'),Q(1,'A sentence says, “The prophet foretold the drought.” What did the person do?','predicted it before it happened','caused it by irrigation','measured it after it ended','To foretell is to predict; the sentence describes a prediction, not causing or measuring.','meaning'),Q(1,'Which use is figurative rather than religious?','The prophet of open-source software predicted its influence.','The prophet recited a sacred message to the congregation.','The prophet was asked to interpret the oracle.','Calling an innovator a prophet extends the word to someone who anticipates or advocates a future trend.','context')]);
P('propinquity','From Latin propinquitas, from propinquus “near”; the English noun denotes nearness, including social or familial closeness.',C('propinquity.s1','书面','Their propinquity to the station made the late train a practical option.','他们离车站很近，因此晚班列车成了可行选择。','propinquity to + place','正式词；常用于描述空间或关系上的接近。','to the station 明确表空间邻近。'),M('The propinquity between the two villages is twenty miles.','The distance between the two villages is twenty miles.','propinquity 表示接近状态，不是以英里计量的距离；可说 the propinquity of the villages made travel easy。','meaning'),[Q(1,'In “The houses’ propinquity encouraged the neighbors to meet,” what does propinquity mean?','closeness in location','similarity in architectural style','ownership by one family','Propinquity means nearness; here the houses are geographically close.','meaning'),Q(1,'Which sentence uses propinquity correctly?','The school’s propinquity to the library saves students a long walk.','The school’s propinquity costs less than the library.','The school propinquity the library every morning.','The noun can take to when naming what something is near.','grammar'),Q(1,'Which word is closest in meaning to propinquity here?','nearness','expense','opposition','Propinquity is a formal noun for nearness or closeness.','meaning'),Q(1,'“Family propinquity” most likely concerns closeness of what kind?','kinship or relationship','temperature','spelling','The source sense includes closeness in kinship as well as place.','context')]);
P('propitiate','From Latin propitiare “to render favourable,” from propitius “favourable”; the verb means appease or regain goodwill.',C('propitiate.s1','书面','The villagers left an offering to propitiate the sea god.','村民留下祭品，以求平息海神的怒意。','propitiate + person/deity','正式及物动词；常接被安抚的人或神祇。','祭品旨在安抚海神，符合“求其息怒”。'),M('She propitiated the angry neighbor by insulting him again.','She tried to propitiate the angry neighbor with an apology.','侮辱会激怒而非安抚对方；apology 是符合目标的和解举动。','word-choice'),[Q(1,'Why did the villagers offer a gift to propitiate the deity?','to appease the deity and regain goodwill','to appoint the deity as a village leader','to prove that the deity did not exist','Propitiate means to appease someone powerful or angry through a conciliatory act.','meaning'),Q(1,'Which object can be propitiated in the literal traditional sense?','an offended god','a broken window','a mathematical equation','The verb traditionally applies to a person or deity whose favour is sought.','collocation'),Q(1,'Choose the sentence that uses propitiate correctly.','He brought flowers to propitiate his aunt after the argument.','He propitiated the flowers by putting them in water.','He propitiated the argument into a short one.','The flowers are the conciliatory offering; the aunt is the person being appeased.','grammar'),Q(1,'Which action is most likely to propitiate an offended host?','offering a sincere apology','repeating the insult loudly','ignoring the host for a month','Propitiation aims to restore favour, so an apology is a plausible conciliatory act.','context')]);
P('propitious','From Latin propitius “favourable, gracious,” probably through French; the adjective describes conditions favourable to success.',C('propitious.s1','书面','Clear skies were propitious for the launch of the rescue balloon.','晴朗的天空有利于救援气球升空。','propitious for + event','正式形容词；常描述条件、时机或迹象有利。','天气为行动创造有利条件。'),M('The storm was propitious for the outdoor concert, so it was canceled.','The clear weather was propitious for the outdoor concert.','storm 与取消户外音乐会的结论不构成“有利条件”；应改为晴朗天气或改成不利。','context'),[Q(1,'A propitious start to a project is one that is…','likely to lead to success','already forgotten','deliberately secret','Propitious means favourable or promising for a good result.','meaning'),Q(1,'Which is the most propitious time for a picnic?','a dry, mild afternoon','a night of severe hail','a day when the park is closed','Dry, mild weather is favourable to a picnic.','context'),Q(1,'Complete the phrase: “The signs were propitious ___ a quick recovery.”','for','under','between','The standard construction is propitious for something.','collocation'),Q(1,'If an event is described as propitious, should you expect help or hindrance?','conditions that help it succeed','conditions that make it impossible','no relation to its outcome','The adjective signals favourable conditions or a good chance of success.','meaning')]);
P('proponent','From Latin proponere “to put forward,” through the agent noun proponens; a proponent puts an idea forward and supports it.',C('proponent.s1','政治','As a proponent of renewable energy, she argued for a faster transition.','作为可再生能源的倡导者，她主张加快转型。','proponent of + cause/idea','名词；常用 of 引出其支持的主张。','of renewable energy 标明她支持的议题。'),M('The proponent opposed the plan at every meeting but was called its supporter.','The opponent opposed the plan at every meeting.','opposed 表示反对；反对者应称 opponent，而 proponent 是支持者。','confusable'),[Q(1,'A proponent of longer library hours would most likely…','argue in favor of keeping libraries open longer','demand that every library close','avoid expressing any view on library hours','A proponent supports or advocates the stated proposal.','meaning'),Q(1,'Which preposition commonly follows proponent when naming a cause?','of','into','beneath','The usual pattern is a proponent of an idea, policy, or cause.','collocation'),Q(1,'In a debate, what distinguishes a proponent from an opponent?','the proponent supports the proposal','the proponent records the debate','the proponent must remain neutral','A proponent advocates the proposal; an opponent argues against it.','distinction'),Q(1,'Which is a plausible proponent’s statement?','“I support the measure because it will reduce waste.”','“I reject the measure and want it withdrawn.”','“I have not read the measure and take no position.”','The first speaker explicitly supports the measure.','context')]);
P('proportion','From Latin proportio “comparative relation, symmetry,” from pro “for” + portio “part”; English uses include ratio, share, and balanced relation.',[C('proportion.s1','数学','The proportion of recycled paper rose from one quarter to one half.','再生纸所占比例从四分之一升至二分之一。','proportion of + whole','常用 the proportion of A；可表达部分与整体的数量关系。','分数明确说明整体中的份额。'),C('proportion.s2','通用','A large proportion of the budget went to school repairs.','预算中的很大一部分用于学校维修。','a proportion of + plural/uncountable noun','可指整体中的一部分，常与 large/small 连用。','此处表示预算份额。'),C('proportion.s3','艺术','The architect checked the proportions of the doorway against the room.','建筑师对照房间检查门口各部分是否协调。','proportions of + object','复数常指各部分之间的均衡、相称。','多部分尺寸之间的协调对应义项3。')],M('The proportion of the cake was delicious, so we ordered another.','A slice of the cake was delicious, so we ordered another.','proportion 通常指比例关系或份额，不是可直接吃的一块；slice 才是具体一片。','word-choice'),[Q(1,'If 30 of 100 students bike to school, what is the proportion who bike?','30 percent','30 kilometers','30 students per teacher','A proportion is the part compared with the whole: 30 out of 100 equals 30 percent.','measurement'),Q(2,'“A small proportion of the funding was spent on travel” means…','a small share of the total funding','the entire funding was travel money','the funding had an incorrect shape','Here proportion means a share or part of a whole.','meaning'),Q(3,'An artist adjusts the proportions of a face. What is being adjusted?','the relative size and balance of its parts','the number of people in the portrait','the price of the paint','Artistic proportions concern the relation and balance among parts.','context'),Q(1,'Which phrase means “the relationship between two quantities”?','the proportion of A to B','a portion under the table','a proposal for B','Proportion can describe the ratio or comparative relation between amounts.','meaning')]);
P('proportional','From Latin proportionalis, from proportio “relation of parts”; the adjective means corresponding in size or amount.',C('proportional.s1','科学','The fee is proportional to the number of pages printed.','费用与打印页数成正比。','proportional to + quantity','常用 be proportional to，表示随另一数量相应变化。','费用按页数对应变化。'),M('The monthly fee is proportional with the number of users.','The monthly fee is proportional to the number of users.','固定搭配是 proportional to，而不是 proportional with。','collocation'),[Q(1,'If cost rises in proportion to distance, the cost is…','proportional to distance','independent of distance','always the same for every trip','A proportional cost changes in a corresponding relation to distance.','meaning'),Q(1,'Complete: “The image is proportional ___ the original.”','to','at','for','The established phrase is proportional to.','collocation'),Q(1,'A proportional increase of 10% means the change is measured…','as a corresponding percentage of the original amount','only in centimeters','without reference to the original','Proportional change is relative to the amount it changes from.','meaning'),Q(1,'Which example best illustrates proportional pay?','Pay increases with hours worked at a fixed hourly rate.','Everyone receives the same total pay regardless of hours.','Pay is decided by shoe color.','At a fixed rate, pay corresponds proportionally to hours.','context')]);
P('proportionally','From proportional + -ly; proportional derives from Latin proportio, “relation of parts.” The adverb means by a corresponding ratio or degree.',C('proportionally.s1','通用','The grant was divided proportionally among the four departments.','补助按比例分给了四个部门。','divide/allocate proportionally','副词修饰分配行为，说明各份额按既定比率变化。','分配方式按比例而不是平均或随机。'),M('Each team received proportionally the same fixed amount, regardless of size.','Each team received the same fixed amount, regardless of size.','固定等额且不考虑规模并非按比例分配；删去 proportionally 才准确。','meaning'),[Q(1,'If a bill is split proportionally to income, what determines each person’s share?','each person’s income relative to the total','the order in which people arrived','each person’s favorite food','Proportionally signals that shares track the relative income amounts.','context'),Q(1,'Which sentence uses proportionally as an adverb?','The costs rose proportionally with the number of units.','The proportionally of costs surprised us.','They bought a proportionally of units.','Proportionally modifies the verb phrase rose and describes how the costs changed.','grammar'),Q(1,'What does proportionally distributed funding avoid?','shares unrelated to the agreed ratio','all numerical comparisons','any spending at all','A proportional distribution follows a specified relation among shares.','meaning'),Q(1,'Which paraphrase best matches “The seats were allocated proportionally”?','The allocation followed the relevant relative shares.','Every group got an unrelated random count.','The seats were allocated after the event ended.','Proportionally means in a way that corresponds to proportions or ratios.','meaning')]);
P('proportionately','From proportionate + -ly; proportionate is based on Latin proportio “comparative relation.” The adverb means in a suitably corresponding amount.',C('proportionately.s1','通用','The subsidy was reduced proportionately when each household’s usage fell.','各户用量下降时，补贴也按相应比例减少。','change proportionately with/to','说明变化幅度与参照量相称。','用量与补贴相应下降。'),M('The subsidy rose proportionately by exactly the same number of dollars for every household, whatever its usage.','The subsidy rose by the same number of dollars for every household, whatever its usage.','对所有家庭加同一固定金额不体现按比例或相称变化，故 proportionately 不成立。','meaning'),[Q(1,'A proportionate response is scaled to the situation. If costs rise proportionately, they rise…','in a corresponding relation to the relevant change','without any relation to the relevant change','only after being hidden','Proportionately describes a corresponding, suitably scaled change.','meaning'),Q(1,'Choose the correct completion: “The payment changed proportionately ___ output.”','to','from','beneath','The standard relation is proportionately to the quantity used as a comparison.','collocation'),Q(1,'Which situation is proportionate?','A team’s budget grows in line with its increased workload.','A tiny error receives a life-long ban.','Every budget is set by drawing a random card.','A proportionate change corresponds sensibly to the change in workload.','context'),Q(1,'How does proportionately differ from merely “equally”?','It emphasizes a corresponding ratio or scale, not necessarily identical amounts.','It always means each person gets exactly the same amount.','It refers only to a geometric shape.','Proportionately tracks relative size or change; equal shares can be a different rule.','distinction')]);
P('proposal','From propose + -al; propose comes through Old French proposer from Latin proponere “put forward.” A proposal is a plan or suggestion put forward for consideration.',C('proposal.s1','商务','The committee reviewed her proposal for a low-cost bus route.','委员会审阅了她提出的低成本公交线路方案。','proposal for + plan; submit/review a proposal','正式提出供讨论或决定的计划、建议。','committee reviewed a concrete plan.','商务'),M('The proposal was a person who submitted the plan.','The proposer was the person who submitted the plan.','proposal 是计划本身；提交计划的人是 proposer。','confusable'),[Q(1,'What did the committee review?','a suggested plan for a bus route','the bus driver’s uniform','a record of last year’s weather','A proposal is a plan or suggestion submitted for consideration.','meaning'),Q(1,'Which verb naturally combines with proposal?','submit','breathe','swim','People submit, review, accept, or reject a proposal.','collocation'),Q(1,'A proposal differs from a proposer because it is…','the plan rather than the person suggesting it','the person rather than the plan','the final result of a vote','The proposal is the suggested plan; a proposer is the person who puts it forward.','distinction'),Q(1,'Which is most likely to appear in a project proposal?','a description of the planned work and its cost','a recipe with no connection to the project','a list of unrelated birthdays','A proposal presents a plan for consideration, often with methods and costs.','context')]);
P('propose','From Latin proponere “to put forward,” via Old French proposer; meanings include suggest, intend, and ask someone to marry.',[C('propose.s1','通用','The engineer proposed a safer design for the bridge.','工程师提出了一种更安全的桥梁设计。','propose + noun / that-clause','及物，提出建议或方案。','safer design 是提交讨论的建议。'),C('propose.s2','书面','We propose to publish the results in June.','我们打算在六月公布结果。','propose to do','正式表达计划或意图。','to publish 表明意图。'),C('propose.s3','生活','He proposed to Maya during their walk by the river.','他在河边散步时向玛雅求婚。','propose to + person','此义是求婚；人前常用 to。','Maya 是被求婚对象。')],M('The engineer proposed us a safer design for the bridge.','The engineer proposed a safer design for the bridge to us.','propose 通常不按双宾语结构 propose someone something；用 propose something to someone。','grammar'),[Q(1,'“The council proposed a new cycle lane.” What did it do?','put forward the idea for consideration','build the lane before discussing it','cancel every road project','Propose in sense 1 means to suggest or put forward a plan.','meaning'),Q(2,'Which sentence expresses an intention?','I propose to finish the report tonight.','I proposed to my partner at dinner.','I proposed the report to the committee.','Propose to do something means intend or plan to do it.','distinction'),Q(3,'In “Lee proposed to Sam,” what happened?','Lee asked Sam to marry him','Lee offered Sam a job','Lee introduced Sam to the committee','Propose to a person can mean ask that person to marry you.','meaning'),Q(1,'Choose the standard pattern for offering an idea to a group.','propose a change to the group','propose the group a change','propose at the group a change','A change is proposed to the people who will consider it.','grammar')]);
P('proposer','From propose + agent suffix -er; propose ultimately comes from Latin proponere, “put forward.” A proposer is the person who makes a proposal.',C('proposer.s1','通用','The proposer explained why the motion should be debated.','提案人解释了为什么应当讨论这项动议。','proposer of a motion/proposal','指提出方案或动议的人，而非方案本身。','此人解释并提交动议。'),M('The proposer was approved by the board, so the plan began.','The proposal was approved by the board, so the plan began.','被批准的是提案或计划；proposer 指提出它的人。','confusable'),[Q(1,'Who is the proposer in a meeting?','the person who puts forward a motion','the person who counts the chairs','the motion itself','The proposer is the person who makes the proposal.','meaning'),Q(1,'The proposer of an amendment is…','the person who suggests the amendment','the amended text only','the person who must reject it','The noun names the person proposing an amendment.','meaning'),Q(1,'Which sentence uses proposer correctly?','The proposer answered questions about the plan.','The proposer was printed on page three as the plan itself.','We proposer the plan yesterday.','A proposer is a person and can answer questions about their proposal.','grammar'),Q(1,'If a proposal passes, what did the proposer do earlier?','put it forward for consideration','erase it from the agenda','vote against their own name','A proposer first introduces or advances the proposal.','context')]);
P('proposition','From Latin propositio “a setting forth,” from proponere “put forward”; English uses include a suggested plan and a statement that can be proved.',[C('proposition.s1','通用','The vendor made a simple proposition: pay once and receive lifetime access.','商家提出了一个简单方案：一次付费，终身使用。','make/accept/reject a proposition','可指供考虑或接受的提议、交易条件。','pay-once offer is a proposal.','商业'),C('proposition.s2','科学','“Every even number greater than two is divisible by two” is a mathematical proposition.','“每个大于二的偶数都能被二整除”是一个数学命题。','proposition that + clause','逻辑或数学中可判定真假的陈述。','该句陈述可检验的数学主张。','数学')],M('The proposition was proved by the mathematician, so she submitted the business offer.','The proposal was submitted as a business offer.','商业提议可以提交或接受；被证明真假的陈述才是逻辑命题，需依语境区分。','distinction'),[Q(1,'A restaurant calls its meal deal “an attractive proposition.” What does proposition mean?','an offer or arrangement to consider','a mathematical proof only','a person who owns the restaurant','In commercial use, a proposition is an offer or suggested arrangement.','context'),Q(2,'A proposition in logic is a statement that…','can be evaluated as true or false','must be a question','names the person making an offer','Logical propositions make claims that can be assessed for truth.','meaning'),Q(1,'Which sentence uses proposition in its business sense?','The supplier offered a proposition with a lower price for a longer contract.','The proposition has no truth value because it is a theorem.','She propositioned the number into an equation.','A contract offer is a commercial proposition.','context'),Q(2,'Which is most clearly a logical proposition?','The moon orbits Earth.','Please close the door.','What time is it?','A proposition is a declarative statement that can be judged true or false.','distinction')]);
P('propound','From Latin proponere “to put forward,” through a learned formation; propound means formally present an idea for discussion.',C('propound.s1','学术','The researchers propounded a theory that linked sleep to memory.','研究人员提出了一种把睡眠与记忆联系起来的理论。','propound a theory/argument','正式及物动词，提出供评议的理论或观点。','theory is put forward for examination.','学术'),M('The researchers propounded the theory to be true by running one test.','The researchers proposed the theory and tested it with one experiment.','propound 表示提出观点，不等于证明其为真；证明需 evidence supports/proves the theory。','meaning'),[Q(1,'What does it mean to propound a theory?','to put it forward for consideration','to hide it from all readers','to prove it beyond every doubt','Propound means formally to present or advance an idea, not necessarily prove it.','meaning'),Q(1,'Which object most naturally follows propound?','an argument','a sandwich','a temperature','Propound is a formal verb used for theories, arguments, or proposals.','collocation'),Q(1,'A historian propounded a new explanation. What is the next reasonable step?','other scholars examine the explanation','the explanation becomes true automatically','the historian deletes all evidence','Propounding introduces an explanation for consideration; it remains open to evaluation.','context'),Q(1,'Which is closest to propound in academic writing?','put forward','take apart','look after','Propound means to put an idea or theory forward.','meaning')]);
P('proprietary','From proprietor + -ary, ultimately from Latin proprietarius “owner’s”; it describes ownership or products controlled by an owner.',C('proprietary.s1','法律','The company uses proprietary software that competitors cannot freely copy.','该公司使用竞争对手不能随意复制的专有软件。','proprietary software/technology','形容词；强调由特定所有者控制或拥有。','company-controlled software fits ownership sense.','法律'),M('The open standard was proprietary because everyone could copy and modify it without restriction.','The open standard was not proprietary because everyone could copy and modify it without restriction.','不受限制地复制、修改与专有控制相反；应否定 proprietary。','meaning'),[Q(1,'A proprietary formula is one that…','is owned or controlled by a particular company','has no owner and is freely available to all','is automatically a mathematical formula','Proprietary emphasizes ownership or control by a particular party.','meaning'),Q(1,'Which phrase is a common use of proprietary?','proprietary technology','proprietary rainfall','proprietary yesterday','The adjective commonly modifies products, software, information, or technology.','collocation'),Q(1,'Why might a firm protect proprietary information?','to prevent unauthorized use or copying','to ensure nobody can understand ordinary words','to make it public domain','Proprietary information is controlled by its owner and may be restricted.','context'),Q(1,'Which statement best distinguishes proprietary from public-domain material?','Proprietary material is controlled by an owner; public-domain material is not under that exclusive control.','Both words always mean secret military information.','Public-domain material has one private owner.','The key distinction is exclusive ownership/control versus no such exclusive copyright control.','distinction')]);
P('proprietor','From Latin proprietarius “owner,” from proprietas “property”; a proprietor owns a business or property and may also run it.',[C('proprietor.s1','通用','The proprietor of the bookshop repaired its old wooden sign.','书店老板修好了那块旧木招牌。','proprietor of + business/property','指出资或拥有店铺、企业、地产的人。','the person owns the bookshop.','通用'),C('proprietor.s2','通用','The inn’s proprietor greeted each guest at the door.','客栈老板在门口迎接每位客人。','the proprietor of an inn/shop','也可特指小店或客栈的经营业主。','the inn owner personally welcomes guests.','通用')],M('The proprietor rented the shop from its owner, so she was not its tenant.','The proprietor owned the shop; the tenant rented it from her.','proprietor 是所有者；租用房屋的人是 tenant，不能把二者倒置。','confusable'),[Q(1,'Who is the proprietor of a café?','the person who owns the café','a customer ordering lunch','a supplier delivering beans','A proprietor is the owner of a business or property.','meaning'),Q(2,'An inn proprietor greets guests and owns the inn. Which sense is emphasized?','an owner who runs a small establishment','a government inspector','a guest staying for one night','The second sense includes a person who operates an inn or shop.','context'),Q(1,'Which phrase is standard?','the proprietor of the restaurant','the proprietor for the restaurant','the proprietor at owns restaurant','Use proprietor of to identify the business or property.','collocation'),Q(1,'How does a proprietor differ from a tenant?','A proprietor owns the property; a tenant rents it.','A proprietor rents the property; a tenant owns it.','They are always the same person by definition.','The terms identify ownership and rental roles respectively.','distinction')]);
P('proprietorship','From proprietor + -ship, with proprietor from Latin proprietarius “owner”; proprietorship is the state or legal arrangement of ownership.',C('proprietorship.s1','法律','Under sole proprietorship, the founder owns the business personally.','在独资经营形式下，创办人以个人身份拥有企业。','sole proprietorship','常用于法律或商业语境，尤其指独资经营/所有权。','sole ownership is explicit.','法律'),M('They registered a proprietorship to show who proposed the new idea.','They registered a proprietorship to show who owned the business.','proprietorship concerns ownership or business form, not authorship of an idea.','meaning'),[Q(1,'What does sole proprietorship describe?','a business owned by one person','a business owned equally by every customer','a proposal made at a meeting','Sole proprietorship is a form of business ownership by one proprietor.','meaning'),Q(1,'Which topic would likely mention proprietorship?','the legal ownership structure of a small business','the pronunciation of a poem','the weather forecast for a harbor','The word concerns ownership, especially a business’s legal form.','context'),Q(1,'Complete: “The shop operates as a sole ___.”','proprietorship','proprietor','proprietary','Proprietorship is the noun for the ownership arrangement; proprietor is the owner.','word-formation'),Q(1,'If a company changes its proprietorship, what may have changed?','who owns it or its ownership arrangement','the color of its logo only','the meaning of its name in a poem','Proprietorship refers to ownership or the structure under which it is held.','meaning')]);
P('propriety','From Latin proprietas “fitness, propriety,” from proprius “one’s own”; propriety means socially suitable conduct or accepted conventions.',[C('propriety.s1','通用','The judge questioned the propriety of discussing the case with a witness.','法官质疑与证人讨论此案是否得体。','the propriety of + noun/gerund','指某行为是否合乎情理、礼貌或规范。','judge assesses appropriateness.','法律'),C('propriety.s2','通用','The manual explains the proprieties expected at a formal dinner.','手册介绍了正式晚宴应遵守的礼节。','social proprieties','复数 proprieties 可指礼节或社会规范。','formal dinner etiquette is the plural sense.','礼仪')],M('Her impropriety at the ceremony showed perfect propriety.','Her respectful behavior at the ceremony showed propriety.','impropriety 是不当行为，与 propriety（得体）含义相反。','confusable'),[Q(1,'A review of the propriety of an action asks whether it is…','appropriate and proper','expensive and profitable','fast and mechanical','Propriety concerns whether conduct is proper or suitable.','meaning'),Q(2,'“The proprieties of court” refers to…','accepted rules of behavior in court','the judges’ private properties','the court’s mathematical proportions','Plural proprieties can mean conventions or etiquette.','meaning'),Q(1,'Which sentence uses propriety correctly?','She doubted the propriety of accepting a gift from the bidder.','She measured the propriety in liters.','She propriety accepted the gift.','The noun can name the appropriateness of an action.','grammar'),Q(1,'What would most clearly violate dinner propriety?','speaking politely and waiting to be served','throwing food at another guest','thanking the host','Propriety refers to accepted manners; throwing food is clearly improper.','context')]);
P('propulsion','From Latin propellere “drive forward” (pro- “forward” + pellere “push”), with -sion forming a noun; propulsion is forward-driving force or its method.',[C('propulsion.s1','通用','The boat’s electric motor provides quiet propulsion across the lake.','电动马达为小船提供安静的推进力，使其驶过湖面。','provide propulsion; propulsion by + method','可指推动物体前进的力或过程。','motor supplies forward force.','通用'),C('propulsion.s2','通用','The course compares rocket propulsion with jet propulsion.','课程比较火箭推进技术与喷气推进技术。','rocket/jet propulsion','也指推动车辆或飞行器的技术类别。','compares technical methods.','科技')],M('The engine’s propulsion kept the stationary boat from moving forward.','The engine’s propulsion drove the boat forward.','推进力的方向意义与 stationary/not moving forward 矛盾；改为推动前进。','meaning'),[Q(1,'What does propulsion do to a vehicle?','pushes it forward','records its history','measures its color','Propulsion is the force or process that drives something forward.','meaning'),Q(2,'Rocket propulsion is best understood as…','a method of making a rocket move','a guide to writing a novel','a system for measuring rainfall','Sense 2 names a field or method of vehicle propulsion.','context'),Q(1,'Which phrase is natural?','a propulsion system','a propulsion apology','a propulsion yesterday','Propulsion commonly combines with system, method, or technology.','collocation'),Q(1,'A spacecraft changes its speed by firing its thruster. This illustrates…','propulsion','propriety','proposition','The thruster produces forward or directional motion, which is propulsion.','meaning')]);
P('prorate','From pro rata, Latin for “according to the rate/portion”; the verb means calculate or allocate a charge in proportion to time or use.',C('prorate.s1','商业','The landlord prorated the rent for the tenant’s first five days.','房东按租户首月实际入住的五天比例计算房租。','prorate a charge by/for + period','常用于账单、工资、保险费按期间或份额折算。','rent reflects a partial month.','商业'),M('We prorated the monthly fee by charging every customer the full amount for one day.','We prorated the monthly fee by charging each customer for the days actually used.','按比例折算部分期间时应按实际占用天数，不是让每人一天付全月费。','measurement'),[Q(1,'A monthly pass costs $90, but a new member joins halfway through the month. To prorate the fee is to…','charge a proportionate amount for the remaining period','charge twice the monthly amount','cancel the pass without calculation','Prorating adjusts a charge to the fraction of the period or service used.','meaning'),Q(1,'Which item is commonly prorated?','rent for a partial month','the color of a car','a word’s pronunciation','Rent or another time-based charge can be adjusted proportionately.','collocation'),Q(1,'Which sentence uses prorate correctly?','The insurer prorated the premium for the short coverage period.','The insurer prorated the customer into a new address.','The premium prorated loudly at noon.','The verb takes a fee or payment as its object and means calculate it proportionally.','grammar'),Q(1,'A worker leaves after six months of a year-end bonus period. A prorated bonus reflects…','the fraction of the period the worker completed','the worker’s shoe size','the full year regardless of time worked','A prorated payment corresponds to the portion of the period completed.','context')]);
P('prorogue','From Latin prorogare “prolong, defer,” from pro- “forward” + rogare “ask”; the parliamentary verb means end a session temporarily.',C('prorogue.s1','政治','The monarch agreed to prorogue Parliament until the autumn session.','君主同意让议会休会，直到秋季会期。','prorogue Parliament/session','正式政治用语；结束一届会期，但不等于解散议会。','the institution is paused until another session.','政治'),M('The prime minister prorogued Parliament permanently and dissolved it for an election.','The prime minister prorogued Parliament until the next session.','prorogue 是暂停会期而非永久解散；永久解散应另用 dissolve。','distinction'),[Q(1,'If Parliament is prorogued, what happens?','its current session is ended or suspended until another session','the building is converted into a court','all members are permanently removed from office','Prorogue refers to ending a parliamentary session, not necessarily dissolving Parliament.','meaning'),Q(1,'Which object commonly follows prorogue?','Parliament','a sandwich','a rainfall','The verb is chiefly used with a parliament or legislative session.','collocation'),Q(1,'How does prorogue differ from dissolve in parliamentary usage?','Prorogue ends a session; dissolve ends the legislature and can lead to an election.','Prorogue means elect; dissolve means debate.','They always mean exactly the same thing.','Prorogation suspends a session while dissolution terminates the legislature.','distinction'),Q(1,'The legislature will reconvene after a break. Which verb best describes the formal ending of the current session?','prorogue','protract','propound','To prorogue is to end or suspend a session until a later one.','context')]);
P('prosaic','From Latin prosa “prose,” via French prosaïque; figuratively it means ordinary and lacking imagination, and literally can mean of prose.',C('prosaic.s1','书面','The report gave a prosaic account of the trip, listing every delay but no excitement.','报告对旅程的叙述平淡乏味，只罗列了每次延误，没有写出任何精彩之处。','prosaic account/detail','多为贬义，形容缺少想象力、令人乏味或过于日常。','the account lacks excitement and imagination.','文学'),M('The prosaic fireworks display was dazzling and full of wonder.','The spectacular fireworks display was dazzling and full of wonder.','dazzling and wondrous 与 prosaic（平淡无奇）相矛盾，应换成 spectacular。','meaning'),[Q(1,'A prosaic description of a sunset is most likely…','plain and lacking imaginative detail','a poem full of vivid metaphors','a technical map of the stars','Prosaic often means ordinary or dull rather than imaginative or poetic.','meaning'),Q(1,'Which would a reviewer call prosaic?','a predictable story with flat language','a startlingly original and moving novel','a sunset that changes color','The word commonly criticizes writing as dull or commonplace.','context'),Q(1,'Which contrast is most direct?','prosaic versus imaginative','prosaic versus rectangular','prosaic versus nocturnal','Prosaic in its figurative sense contrasts with imaginative or poetic.','distinction'),Q(1,'A colleague calls the plan prosaic. What criticism are they making?','It is ordinary and uninspired.','It is impossible to understand because it is in verse.','It is legally prohibited.','The adjective criticizes a lack of originality or excitement.','meaning')]);
P('proscribe','From Latin proscribere “publish the names of outlaws,” from pro- “before” + scribere “write”; later it came to mean officially forbid.',C('proscribe.s1','法律','The city voted to proscribe the sale of fireworks near the hospital.','市议会投票决定禁止在医院附近出售烟花。','proscribe a practice/activity','正式用语，指以权威或法律明令禁止。','a city vote imposes an official ban.','法律'),M('The rule prescribed public smoking, so visitors were forbidden to light cigarettes.','The rule proscribed public smoking, so visitors were forbidden to light cigarettes.','prescribe 通常是规定或开药；proscribe 才表示明令禁止。','confusable'),[Q(1,'If a law proscribes an activity, it…','officially forbids it','recommends it as a hobby','measures its cost','Proscribe means prohibit or condemn by authority.','meaning'),Q(1,'Which verb contrasts with proscribe?','permit','ban','outlaw','Permit means allow, the opposite of proscribe.','distinction'),Q(1,'Which sentence uses proscribe correctly?','The treaty proscribes the use of chemical weapons.','The treaty proscribes a new recipe for dessert.','The treaty proscribed the delegates a pleasant welcome.','A treaty can formally prohibit a practice; the verb takes the prohibited act as object.','grammar'),Q(1,'A school proscribes phones during exams. What does the policy do?','bans students from using phones then','requires every student to buy a phone','records the phone numbers','To proscribe is to forbid, especially by a rule or authority.','context')]);
P('prose','From Latin prosa “straightforward speech,” from prosa oratio; prose is ordinary continuous language, not verse.',[C('prose.s1','文学','The novel’s prose is simple, but its descriptions are vivid.','这部小说的散文体语言简洁，但描写生动。','write/read prose; prose style','指非诗歌的常规句式语言。','novelistic sentences rather than verse.','文学'),C('prose.s2','文学','After the lyrical opening, the essay slipped into dull prose.','抒情的开篇之后，文章转入了乏味平淡的叙述。','plain/dull prose','引申指缺少诗意或想象力的平淡表达。','dull signals the figurative sense.','文学')],M('The sonnet was written in prose, with every line following a fixed rhyme and meter.','The sonnet was written in verse, with every line following a fixed rhyme and meter.','十四行诗按行韵律写成诗体 verse；prose 是不按诗行组织的散文。','distinction'),[Q(1,'How is prose usually distinguished from verse?','Prose uses ordinary sentence form rather than patterned poetic lines.','Prose must always be a single word.','Prose is spoken only and can never be written.','Prose is continuous ordinary language, as opposed to verse’s poetic lineation.','distinction'),Q(1,'Which work is most likely written in prose?','a short story with paragraphs of sentences','a sonnet arranged in metered lines','a list of musical notes only','Stories and essays are normally written in prose.','context'),Q(2,'“The speech descended into prosaic prose” criticizes it as…','plain and unimaginative','highly musical and poetic','scientifically measured','Prose can figuratively suggest flat, unpoetic language; prosaic reinforces that criticism.','meaning'),Q(1,'Choose the natural phrase.','a prose narrative','a prose of five meters per line','a prose to rhyme at the end of every line','Prose narrative is ordinary continuous writing; strict meter and rhyme are features of verse.','collocation')]);
P('prosecute','From Latin prosequi “pursue,” via French; the verb chiefly means bring a criminal case, and can also mean carry an activity through.',[C('prosecute.s1','法律','The state decided to prosecute the driver for leaving the scene.','州政府决定起诉那名肇事后逃逸的司机。','prosecute someone for a crime','法律用法：由公诉方对被告提起并进行刑事诉讼。','state brings a criminal case against the driver.','法律'),C('prosecute.s2','书面','The team prosecuted its research despite the funding delay.','尽管资金延迟，团队仍继续开展研究。','prosecute a plan/course/inquiry','正式义项：继续、贯彻某项计划或活动。','the team carries on an undertaking.','学术')],M('The defense attorney prosecuted the defendant on behalf of the state.','The state prosecutor prosecuted the defendant on behalf of the state.','刑事起诉由公诉方进行；辩护律师代表被告，不是替州政府起诉。','confusable'),[Q(1,'If a state chooses to prosecute a driver, it will…','bring a criminal case against the driver','pay the driver’s insurance claim','ask the driver to write a novel','In legal use, prosecute means bring proceedings against someone accused of a crime.','meaning'),Q(2,'“They prosecuted the inquiry for two years” means they…','continued the inquiry','charged the inquiry with a crime','canceled the inquiry immediately','The formal extended sense is to carry on or pursue an activity.','meaning'),Q(1,'Which role usually prosecutes a criminal case for the state?','a prosecutor','a defense attorney','a juror','The prosecutor conducts the case against the accused on behalf of the state.','context'),Q(1,'Choose the correct pattern for legal use.','prosecute a person for fraud','prosecute a person of fraud','prosecute a person to fraud','The common legal construction is prosecute someone for an alleged offense.','grammar')]);
P('prosecution','From prosecute + -ion, from Latin prosequi “pursue”; it denotes criminal proceedings and the side conducting them.',C('prosecution.s1','法律','The prosecution called two witnesses to establish where the accused had been.','控方传唤了两名证人，以证明被告当时所在的位置。','the prosecution calls/presents evidence','既可指刑事起诉过程，也可集合指控方律师。','collective party presents witnesses.','法律'),M('The prosecution defended the accused and asked the jury to acquit him.','The defense defended the accused and asked the jury to acquit him.','请求陪审团宣告被告无罪是辩方职责；prosecution 是控方。','confusable'),[Q(1,'In court, the prosecution is the side that…','brings the case against the accused','represents the accused as defense counsel','decides the verdict as a jury','The prosecution conducts the case alleging that the accused committed an offense.','meaning'),Q(1,'Which verb commonly combines with prosecution in a trial?','the prosecution presents evidence','the prosecution bakes evidence','the prosecution sleeps evidence','A prosecution may present evidence and call witnesses.','collocation'),Q(1,'If the prosecution fails to prove the charge, what may the court do?','acquit the defendant','sentence the jury','prosecute the evidence','The prosecution bears the case; failure to establish guilt can lead to acquittal.','context'),Q(1,'The prosecution announced that it would continue the case. Which meaning is active?','the legal process or the lawyers conducting it','a person accused of the offense','the judge’s written ruling only','Prosecution names the criminal proceedings or the prosecuting side.','meaning')]);
P('prosecutor','From prosecute + agent suffix -or; the word comes through Latin prosequi, “pursue.” A prosecutor conducts a criminal case for the state.',C('prosecutor.s1','法律','The prosecutor questioned the witness about the missing records.','检察官就失踪的记录询问了证人。','prosecutor questions/calls a witness','指代表国家或公共机关提起刑事案件的人。','the official questions a witness for the case.','法律'),M('The prosecutor represented the accused and argued that the evidence was unreliable.','The defense lawyer represented the accused and argued that the evidence was unreliable.','为被告辩护的是辩护律师；prosecutor 通常代表控方。','confusable'),[Q(1,'What does a prosecutor generally do?','conducts a criminal case against an accused person','serves as the judge who decides the case','records the weather outside court','A prosecutor presents the state’s case against the accused.','meaning'),Q(1,'Which phrase is natural?','the prosecutor presented evidence','the prosecutor was sentenced by the evidence','the prosecutor borrowed a jury','Prosecutors present evidence in court.','collocation'),Q(1,'Who would most likely cross-examine a state witness to challenge the accusation?','the defense lawyer','the prosecutor','the court clerk','Defense counsel challenges the case; the prosecutor presents it.','context'),Q(1,'A prosecutor asks the court to convict a defendant. Whom does the prosecutor represent?','the state or public authority','the accused person as personal counsel','the jury as its elected leader','The prosecutor represents the state or public authority in a criminal case.','meaning')]);
P('prospect','From Latin prospectus “view, outlook,” from prospicere “look forward”; English includes future possibility, a view, a potential customer, and searching for minerals.',[C('prospect.s1','通用','The prospect of a shorter commute made the new job attractive.','通勤时间可能缩短，这一前景让新工作很有吸引力。','the prospect of + noun/gerund','指未来可能发生的事，常搭配 prospect of。','a possible future outcome is attractive.','通用'),C('prospect.s2','书面','From the tower, visitors enjoyed a prospect of the entire valley.','游客从塔上欣赏到整个山谷的景色。','a prospect of + view','较正式地指可看到的景色或视野。','view from a high point.','书面'),C('prospect.s3','商业','The sales team followed up with each promising prospect.','销售团队逐一跟进每位有希望的潜在客户。','a sales/business prospect','商业中指可能成为客户、成员或成功候选者的人/事。','a prospective customer.','商业'),C('prospect.s4','地质','They prospected for copper along the ridge.','他们沿着山脊勘探铜矿。','prospect for minerals','作动词时指勘查寻找矿藏。','search is specifically for mineral deposits.','地质')],M('The company prospected a new customer by sending her a sales brochure.','The company contacted a prospective customer by sending her a sales brochure.','prospect 作动词通常指勘探矿藏；商业潜客可称 prospect（名词）或 prospective customer。','word-choice'),[Q(1,'“There is little prospect of rain” means…','rain is unlikely to happen','rain has already flooded the town','the view of rain is beautiful','Prospect of an event means its possibility or likelihood.','meaning'),Q(2,'A “prospect over the bay” is…','a view across the bay','a future customer','a mineral survey','The older noun sense can mean a view or outlook.','meaning'),Q(3,'A promising sales prospect is…','a possible future customer','a sales forecast printed on paper','a person who mines copper','In business, prospect can name a potential customer or client.','context'),Q(4,'If geologists prospect for lithium, they…','search for lithium deposits','sell lithium to customers','predict the price of copper','To prospect for a mineral is to search for deposits of it.','meaning')]);
P('prospecting','From prospect + -ing; prospect traces to Latin prospicere “look forward/look out.” Prospecting is systematic searching for mineral deposits.',C('prospecting.s1','地质','Prospecting along the river revealed traces of gold in the gravel.','沿河勘探发现砾石中有金的痕迹。','prospecting for + mineral','名词，指为寻找矿物而进行的勘查。','search uncovers mineral traces.','地质'),M('The prospecting team searched for mineral deposits but called the work prospecting for customers.','The sales team searched for new clients; the geologists went prospecting for mineral deposits.','名词 prospecting 的专业常用义是勘探矿物；客户开发叫 prospecting for clients 的销售用法需明确销售语境，而非地质意义。','context'),[Q(1,'What is the usual geological purpose of prospecting?','to search for valuable mineral deposits','to calculate a company’s annual taxes','to polish a stone already mined','Prospecting is the search and preliminary examination for mineral resources.','meaning'),Q(1,'Which phrase is standard in mining?','prospecting for gold','prospecting gold into jewelry','prospecting to the mine','Prospecting for names the mineral being sought.','collocation'),Q(1,'A geologist samples rock while prospecting. What is the geologist trying to locate?','a mineral deposit','a theater audience','a legal defendant','Prospecting in geology seeks minerals or ore deposits.','context'),Q(1,'Which activity is most closely related to prospecting?','surveying ground for signs of copper','writing a prospectus for investors','viewing a valley from a tower','Prospecting means searching for minerals, not preparing a booklet or enjoying a view.','distinction')]);
P('prospective','From Latin prospectivus, from prospicere “look forward”; the adjective means expected or likely in the future, or considered for a future role.',C('prospective.s1','通用','The university sent a guide to prospective students before the application deadline.','大学在申请截止日前向未来的申请者寄送了一份指南。','prospective + role/person','指可能成为、预期将成为某身份的人或事。','students are considering future enrollment.','教育'),M('The prospective graduate had already received her diploma five years earlier.','The former graduate had already received her diploma five years earlier.','已毕业的人是 former graduate，不再是 prospective student/graduate（未来可能成为）。','meaning'),[Q(1,'A prospective employee is someone who…','may be hired in the future','has already retired from the company','recruits the employer','Prospective indicates a possible future status.','meaning'),Q(1,'Which phrase is common?','prospective buyers','prospective yesterday','prospective of buyers','The adjective commonly modifies people being considered as future buyers, students, or members.','collocation'),Q(1,'A prospective student visits campus before applying. Why is the adjective appropriate?','the person may become a student later','the person teaches every class there','the person has already graduated','Prospective describes a possible future student, not a current or past one.','context'),Q(1,'Choose the best replacement: “The company interviewed prospective suppliers.”','potential suppliers','former suppliers','unrelated suppliers from the past','Prospective suppliers are candidates that may supply the company later.','meaning')]);
P('prospector','From prospect + agent suffix -or; prospect derives from Latin prospicere “look out.” A prospector searches for minerals or valuable deposits.',C('prospector.s1','地质','The prospector tested the stream gravel for traces of tin.','勘探者检测了溪流砾石中是否含有锡的痕迹。','a prospector searches for + mineral','指寻找矿藏的个人，常见于采矿史或地质语境。','person conducts mineral search.','地质'),M('The prospector located a gold deposit by advertising shoes to shoppers.','The prospector located a gold deposit by examining mineral-bearing rock.','找矿者靠地质勘查而非向顾客推销鞋子；错误句把 prospector 混同销售员。','context'),[Q(1,'What is a prospector looking for?','valuable minerals or deposits','a suitable wedding venue','a missing court transcript','A prospector searches an area for minerals such as gold or ore.','meaning'),Q(1,'Which activity suits a prospector?','testing rock samples for copper','designing a book’s prospectus','prosecuting a defendant','Prospectors examine terrain or samples to find mineral deposits.','context'),Q(1,'A prospector is best described as…','a person who prospects','a mineral deposit itself','a machine used only for weighing ore','The agent noun refers to the person doing the search.','word-formation'),Q(1,'Choose a natural phrase.','a gold prospector','a prospecting prosecutor','a prospector of court verdicts','Gold prospector is a standard noun phrase for someone searching for gold.','collocation')]);
P('prospects','From prospect, via Latin prospectus “outlook”; plural prospects commonly means chances or opportunities for future success.',C('prospects.s1','通用','Her prospects improved after she completed the engineering course.','完成工程课程后，她的前途更有希望了。','career/job/future prospects','复数常指未来成功或发展的机会。','training increases chances of success.','通用'),M('His prospects are excellent because he has no chance of finding work.','His prospects are poor because he has no chance of finding work.','“没有机会找到工作”与 excellent prospects（前景很好）相矛盾。','meaning'),[Q(1,'Good job prospects are…','strong chances of finding or succeeding in work','a list of current employees’ names','a view from an office window','Prospects commonly means future chances or opportunities.','meaning'),Q(1,'Which phrase is natural?','bright prospects','prospects loudly','prospects of a screwdriver','Bright prospects is a conventional expression for a promising future.','collocation'),Q(1,'If a graduate’s prospects improve, what becomes more likely?','future success or employment','the graduate’s past becomes longer','the office window gets larger','Improved prospects mean better chances of future success or opportunity.','context'),Q(1,'Why is prospects plural in “She has excellent prospects”?','It refers broadly to future chances and opportunities.','It must refer to several landscapes.','It is the past tense of prospect.','The plural noun is conventionally used for future opportunities or chances.','grammar')]);
P('prospectus','From Latin prospectus “view, outlook,” via French; a prospectus is a formal document outlining an institution, course, or investment offer.',C('prospectus.s1','教育','Applicants downloaded the college prospectus to compare degree programs.','申请者下载了学院招生简章，以比较各个学位项目。','college/course prospectus','正式说明机构或课程内容的手册、文件；也可说明证券发行。','document provides course details.','教育'),M('The prospectus enrolled the student in a course without an application.','The student used the prospectus to compare courses before applying.','prospectus 是介绍课程的文件，不是执行招生或注册的人员/系统。','confusable'),[Q(1,'What information would a college prospectus contain?','details about courses and the institution','a student’s private diary','the final marks for an unheld exam','A prospectus introduces the institution and its courses to prospective students.','context'),Q(1,'A company issues a prospectus before selling shares. Why?','to provide formal information about the investment offer','to appoint a prosecutor','to record a private conversation','An investment prospectus describes the securities and the issuing organization.','meaning'),Q(1,'Which verb naturally combines with prospectus?','publish','prosecute','prostrate','An institution may publish or issue a prospectus.','collocation'),Q(1,'A prospectus is mainly a…','descriptive document for prospective readers or investors','person who proposes a plan','view seen from a hill','The noun names a formal booklet or document, not the person or the view itself.','distinction')]);
P('prosper','From Latin prosperare “cause to succeed,” from prosperus “favorable”; the verb means thrive or do well.',[C('prosper.s1','经济','The family business began to prosper after it expanded online.','这家家族企业转向线上扩张后开始兴旺起来。','business/economy prospers','常指经济上成功、繁荣。','business succeeds and grows.','经济'),C('prosper.s2','通用','With steady care, the young trees prospered in the sheltered garden.','在持续照料下，幼树在避风的花园里茁壮成长。','plants/people prosper','也可泛指健康成长、顺利发展。','trees grow successfully.','通用')],M('The business prospered into bankruptcy as its sales doubled and debts vanished.','The business prospered as its sales doubled and debts fell.','繁荣兴旺与破产相矛盾；若销量增长、债务减少，应写 prospered。','meaning'),[Q(1,'If a business prospers, it…','succeeds and grows, often financially','closes before opening','becomes less successful each year','Prosper means to do well or become successful.','meaning'),Q(2,'“The seedlings prospered in the warm greenhouse” means they…','grew healthily','were sold at a loss','were prohibited from growing','Sense 2 extends prosper to healthy growth or successful development.','context'),Q(1,'Which is a natural subject of prosper?','a small enterprise','a broken ruler only','a canceled appointment','Businesses and people can prosper by doing well or thriving.','collocation'),Q(1,'A village prospers after a new bridge opens. What is implied?','the village develops successfully','the bridge has no effect and the village disappears','the village is being legally prosecuted','Prosper describes successful development, often supported by improved opportunities.','meaning')]);
P('prosperity','From prosperous + -ity; prosperous derives from Latin prosperus “favorable.” Prosperity is a state of success and material well-being.',C('prosperity.s1','金融','The region’s prosperity depended on reliable trade routes and skilled workers.','该地区的繁荣有赖于可靠的贸易路线和熟练工人。','economic/regional prosperity','通常指经济和生活状况良好、成功兴旺的状态。','trade and skill support regional wealth.','金融'),M('The town’s prosperity increased as every business failed and unemployment soared.','The town’s hardship deepened as businesses failed and unemployment soared.','企业倒闭、失业上升表示困境加深，并非 prosperity 增长。','meaning'),[Q(1,'A period of national prosperity is one of…','economic success and well-being','widespread economic collapse','uncertain pronunciation','Prosperity is the condition of flourishing, especially economically.','meaning'),Q(1,'Which phrase is conventional?','shared prosperity','prosperity a court','prosperity of silently','Prosperity commonly combines with shared, economic, or lasting.','collocation'),Q(1,'If prosperity spreads to rural areas, what is spreading?','economic opportunity and success','a legal ban on farming','a mineral sample','Prosperity refers to flourishing conditions and material well-being.','context'),Q(1,'Which adjective is formed from prosperity?','prosperous','prosecuted','propitiousness','Prosperous is the adjective describing a flourishing or successful state.','word-formation')]);
P('prosperous','From Latin prosperus “favorable, fortunate,” via Old French; the adjective means successful and flourishing, often financially.',[C('prosperous.s1','通用','The prosperous coastal region invested in hospitals and public transit.','这个繁荣的沿海地区投资建设医院和公共交通。','prosperous region/economy','常描述经济发展良好、富裕的地区。','public services reflect regional wealth.','地理'),C('prosperous.s2','通用','It became a prosperous repair business with a loyal customer base.','凭借忠实的顾客群，它发展成一家兴旺的维修企业。','prosperous business/career','也可描述经营成功、收入良好的企业或个人事业。','the business is financially successful.','商业'),C('prosperous.s3','通用','The family wished the newlyweds a prosperous future together.','家人祝愿这对新人未来幸福顺遂。','a prosperous future','书面可表示未来顺利、吉祥。','used as a wish for favorable success.','通用')],M('The prosperous firm reported mounting losses and shut all its branches.','The struggling firm reported mounting losses and shut all its branches.','持续亏损并关闭门店并不符合 prosperous（兴旺的）；struggling 与事实相符。','meaning'),[Q(1,'A prosperous economy generally has…','strong business activity and material well-being','no jobs and collapsing trade','only a large population','Prosperous describes a successful, flourishing economy.','meaning'),Q(2,'Which business would be called prosperous?','one with steady growth and healthy profits','one that has closed and cannot pay its bills','one whose sign is painted green','A prosperous business succeeds economically.','context'),Q(3,'In a wish for a “prosperous future,” prosperous means…','successful and favorable','already completed yesterday','strictly agricultural','The adjective can express hope for future success and good fortune.','meaning'),Q(1,'Which is the opposite of a prosperous company?','a failing company','a thriving company','a profitable company','A failing company contrasts with prosperous, which means thriving or successful.','distinction')]);
P('prostitution','From Latin prostituere “expose publicly, offer for sale,” from pro- “before” + statuere “set up”; English names sex in exchange for payment and figurative corruption of a role or talent.',C('prostitution.s1','社会','The report examined how poverty can make people vulnerable to prostitution.','报告调查了贫困如何使人更容易陷入卖淫活动。','prostitution; forced/child prostitution','指以性行为换取报酬，也可比喻把职责或才能用于卑劣目的。','report discusses social vulnerability to commercial sex.','社会'),M('The museum called the careful conservation of the painting prostitution of its art.','The museum called the sale of its collection a prostitution of its public mission.','细致修复并不构成“糟蹋职责”；若要用引申义，需说明把公共使命出卖或滥用。','meaning'),[Q(1,'In its literal social sense, prostitution involves…','sexual services exchanged for payment','selling paintings at an auction','offering a plan for public debate','The word refers to commercial sex, not ordinary sales or proposals.','meaning'),Q(1,'“The prostitution of public office” is a figurative criticism of…','using public duties for corrupt or unworthy purposes','protecting a public building from fire','holding an election','The figurative use condemns degrading or corrupt misuse of a role.','context'),Q(1,'Which collocation is meaningful?','prostitution of power','prostitution of a rainfall','prostitution to the color blue','The figurative construction prostitution of power describes corrupt misuse of authority.','collocation'),Q(1,'Why is prostitution sometimes used figuratively?','It suggests degrading or corrupt use of something that should be respected.','It means a person has proposed a new idea.','It is another word for a public library.','The figurative sense extends the idea of selling or degrading a role or talent.','meaning')]);
P('prostrate','From Latin prosternere “throw down,” from pro- “forward/down” + sternere “spread out”; as adjective it means lying flat or exhausted, and as verb it means overcome.',[C('prostrate.s1','通用','The worshippers lay prostrate before the shrine.','朝拜者俯伏在神龛前。','lie/be prostrate before/on','形容词，指脸朝下平伏，常用于敬拜或屈服场景。','body is laid flat before shrine.','宗教'),C('prostrate.s2','通用','Heat and dehydration left the hikers prostrate beside the trail.','高温和脱水使徒步者筋疲力尽，瘫倒在小路旁。','leave/render someone prostrate','形容词，引申为极度疲惫、无力行动。','physical condition is utter exhaustion.','通用'),C('prostrate.s3','通用','The defeat prostrated the rival army and ended its advance.','这场失败击溃了敌军，终止了它的推进。','prostrate an opponent','及物动词，指彻底击败、使屈服。','defeat overcomes the opponent.','通用')],M('After the race, the exhausted runners stood prostrate and sprinted another lap.','After the race, the exhausted runners lay prostrate and could not move.','prostrate 描写伏倒或筋疲力尽；“站着又冲刺”与该状态冲突。','meaning'),[Q(1,'A person lying prostrate is…','lying flat, often face down','standing upright on a platform','running at full speed','The physical adjective means stretched out flat on the ground.','meaning'),Q(2,'If exhaustion leaves a climber prostrate, the climber is…','so tired that they can barely act','well rested and eager to climb','the leader of a parliament','Sense 2 means completely exhausted or incapacitated.','context'),Q(3,'“The invasion prostrated the kingdom” means the invasion…','overwhelmed or defeated it','made it kneel politely to greet visitors','helped it prosper economically','The verb means to overcome or bring someone or something low.','meaning'),Q(1,'Which sentence uses prostrate as a verb?','The disaster prostrated the small community.','The patient lay prostrate on the cot.','They saw a prostrate figure near the altar.','In the first sentence, prostrated is an action taking the community as object.','grammar')]);
P('protagonist','From Greek prōtagōnistēs “first actor,” from prōtos “first” + agōnistēs “competitor/actor”; it is the central character or leading participant.',C('protagonist.s1','文化','The novel’s protagonist leaves home to uncover the family secret.','小说的主人公离家去揭开家族秘密。','the protagonist of a story','文学中指故事的主要人物；也可指运动或论点的主要倡导者。','the character anchors the narrative.','文学'),M('The novel’s protagonist is the minor shopkeeper who appears once, while the central hero is called the antagonist.','The novel’s protagonist is the central hero, while the opposing character is the antagonist.','protagonist 是主要人物；antagonist 是主要对立者。把只出现一次的小配角称作主人公会误导。','confusable'),[Q(1,'Who is a novel’s protagonist?','the central character whose story is followed','the person who prints the book','the final paragraph of the book','The protagonist is the main character of a story or play.','meaning'),Q(1,'Which role contrasts with protagonist in many stories?','antagonist','narrator’s comma','publisher','An antagonist is a character opposing the protagonist.','distinction'),Q(1,'A campaign’s protagonist might be…','its leading advocate','its smallest poster','a person who opposes every part of it','Protagonist can figuratively mean the leading participant or advocate of a cause.','context'),Q(1,'Which phrase is idiomatic?','the protagonist of the play','the protagonist at the verb','the protagonist under the weather','The usual construction is protagonist of a story, play, or movement.','collocation')]);
P('protect','From Latin protegere “cover in front, shelter,” from pro- “in front” + tegere “cover”; the verb keeps someone or something safe from harm.',[C('protect.s1','通用','A waterproof case protects the camera from dust and rain.','防水盒能保护相机免受灰尘和雨水侵害。','protect something from/against harm','及物动词，保护人或物免受危险、损伤。','case shields camera from environmental threats.','通用'),C('protect.s2','法律','The law protects tenants from sudden eviction without due process.','法律保护租户免遭未经正当程序的突然驱逐。','protect someone from/against; protect rights','也可表示提供法律或制度保障。','law gives tenants legal safeguards.','法律')],M('The helmet protected the cyclist from by making the fall more dangerous.','The helmet protected the cyclist from injury by absorbing the impact.','from 后应接要防止的伤害；安全头盔不会使摔倒更危险。','grammar'),[Q(1,'A helmet protects a rider from…','head injury','a train schedule','a promotion at work','Protect from names the harm prevented by the helmet.','collocation'),Q(2,'If a law protects a tenant’s rights, it…','provides legal safeguards for those rights','removes all legal rights','guarantees that rent is free','The legal sense means give protection or cover under rules or law.','meaning'),Q(1,'Which sentence uses protect correctly?','The gloves protect her hands against the cold.','The gloves protect the cold from her hands.','The gloves protect at cold her hands.','Protect + object + from/against + threat is a standard pattern.','grammar'),Q(1,'A password protects an account by…','helping prevent unauthorized access','increasing the screen brightness','changing the account’s language','Protection means keeping something safe from harm or unwanted access.','context')]);
P('protected','From protect + past-participle suffix -ed; protect comes from Latin protegere “shelter.” Protected means kept safe or legally covered.',C('protected.s1','通用','The protected wetland is closed to vehicles during nesting season.','筑巢季期间，这片受保护的湿地禁止车辆进入。','protected area/species','形容词，说明某物受到保护，免于损害或干扰。','access restriction safeguards habitat.','生态'),M('The protected forest was cut down because nobody had placed it under protection.','The unprotected forest was cut down because nobody had placed it under protection.','既然没有保护措施，就不应称森林为 protected。','meaning'),[Q(1,'A protected species is one that…','has legal or practical safeguards against harm','has already disappeared by definition','is available for unrestricted hunting','Protected means kept safe, often by law or policy.','meaning'),Q(1,'Which collocation is natural?','a protected habitat','a protected yesterday','a protected loudly','Protected commonly describes areas, species, or information.','collocation'),Q(1,'A file marked protected may be…','restricted from unauthorized changes or access','a file with no data','a document that protects the reader from rain','The adjective can mean safeguarded against unwanted access or alteration.','context'),Q(1,'Choose the correct contrast: “A protected site is ___ from development.”','shielded','encouraged','measured','Protected is close in meaning to shielded or safeguarded.','meaning')]);
P('protection','From protect + -ion, from Latin protegere “shelter”; protection is the act or system of keeping someone or something safe.',C('protection.s1','通用','The seedlings need protection from frost during the first week.','幼苗在第一周需要防霜保护。','protection from/against + threat','名词，指防止伤害的行动或措施。','frost is the danger being guarded against.','通用'),M('The raincoat gave the hikers protection to the rain.','The raincoat gave the hikers protection from the rain.','表示防范某种威胁时用 protection from/against，而不是 protection to。','collocation'),[Q(1,'A smoke alarm provides protection by…','warning people of a possible fire','making the fire spread faster','removing every exit','Protection is a safeguard against harm; an alarm warns of danger.','context'),Q(1,'Complete: “The vaccine offers protection ___ the disease.”','against','among','under','The usual preposition is protection against or from a threat.','collocation'),Q(1,'What is the protection of wildlife?','actions and rules that keep wild animals safe','a list of animals for sale','a prediction of tomorrow’s weather','Protection names the act or system of safeguarding.','meaning'),Q(1,'Which word is closest in meaning to protection?','safeguarding','exposure','punishment','Protection is the act of guarding against harm.','meaning')]);
P('protectionist','From protection + -ist; protection is from Latin protegere “shelter.” In economics, a protectionist favors barriers that shield domestic producers from foreign competition.',C('protectionist.s1','经济','The protectionist senator called for a tariff on imported steel.','这位贸易保护主义参议员呼吁对进口钢材征收关税。','protectionist policy/tariff','名词或形容词，涉及保护本国产业免受进口竞争。','tariff shields domestic producers.','经济'),M('The protectionist supported removing all tariffs so imports would face no barriers.','The free-trade advocate supported removing all tariffs so imports would face no barriers.','支持取消贸易壁垒与典型保护主义立场相反。','distinction'),[Q(1,'A protectionist trade policy aims to…','shield domestic industries from foreign competition','ban all domestic manufacturing','make every imported good free','Protectionism favors measures such as tariffs or quotas to protect home producers.','meaning'),Q(1,'Which measure would a protectionist most likely support?','a tariff on imported steel','removing every import restriction','a rule that protects endangered birds only','Tariffs can make imported products less competitive and protect domestic producers.','context'),Q(1,'“Protectionist” can function as…','a noun for an advocate and an adjective for a policy','only a verb meaning protect a child','only an adverb describing speed','The source entry allows noun and adjective uses.','grammar'),Q(1,'Which viewpoint contrasts with protectionist economics?','free-trade advocacy','a call for import quotas','support for tariffs','Free-trade advocates generally favor fewer trade barriers than protectionists.','distinction')]);
P('protective','From protect + -ive; protect is from Latin protegere “shelter.” Protective describes something that provides protection or someone inclined to guard another.',C('protective.s1','通用','Workers wore protective gloves while handling the solvent.','工人处理溶剂时戴着防护手套。','protective clothing/gear','形容词，说明物品用于防止伤害；也能描述关怀保护的态度。','gloves protect against chemical exposure.','职业安全'),M('The protective gloves exposed her skin directly to the solvent.','The unsuitable gloves exposed her skin directly to the solvent.','如果手套使皮肤直接接触溶剂，它们就没有发挥 protective 的保护作用。','meaning'),[Q(1,'Protective goggles are worn to…','guard the eyes against injury','make the eyes more vulnerable','measure the wearer’s height','Protective gear is intended to prevent harm.','meaning'),Q(1,'Which phrase is standard?','protective measures','protective yesterday','protective to a number','Protective commonly modifies measures, clothing, equipment, or behavior.','collocation'),Q(1,'A protective parent is likely to…','try to keep a child safe','encourage the child to face needless danger','avoid knowing whether the child is safe','The adjective can describe a person who wants to protect someone.','context'),Q(1,'Which describes a protective coating?','a layer that prevents damage to the surface','a layer that causes corrosion','a list of surface measurements','Protective means serving to guard against damage.','meaning')]);
P('protector','From protect + agent suffix -or; protect comes from Latin protegere “cover, shelter.” A protector is a person or device that guards against harm.',C('protector.s1','通用','A clear screen protector kept scratches off the phone display.','透明屏幕保护膜避免手机显示屏被刮花。','a protector of/for; screen protector','可指保护者，也可指起防护作用的物品。','accessory guards the screen.','科技'),M('The protector scratched the display and was installed to make it more vulnerable.','The damaged protector scratched the display and needed replacing.','protector 的功能是防护；若它本身造成刮伤，应说明其损坏而非保护目的。','meaning'),[Q(1,'A screen protector is…','a layer that helps guard a screen from scratches','a person who repairs every phone','the screen’s brightness setting','The noun can name an object designed to protect a surface.','meaning'),Q(1,'A protector of a child is most likely…','someone who keeps the child safe','the child’s school timetable','a person who deliberately causes harm','A protector is someone or something that guards against danger.','context'),Q(1,'Which phrase is natural?','a protector against dust','a protector into dust','a protector yesterday','Protector can be followed by against to name the threat guarded against.','grammar'),Q(1,'Which is the agent noun related to protect?','protector','protection','protective','Protector names the person or thing doing the protecting.','word-formation')]);
P('protein','From French protéine, coined from Greek prōteios “primary” (from prōtos “first”), because proteins were regarded as fundamental substances; a nutrient and a class of molecules.',[C('protein.s1','营养','Lentils provide protein as well as fiber.','扁豆既提供蛋白质，也提供膳食纤维。','a source of protein; protein in food','不可数名词常指营养物质；食物含蛋白质。','lentils supply a nutrient.','营养'),C('protein.s2','生物','The lab measured a protein that helps cells repair damaged tissue.','实验室测量了一种帮助细胞修复受损组织的蛋白质。','a specific protein; protein molecule','可数用法指某一种具体蛋白质分子或类别。','one particular molecule is measured.','生物')],M('Eggs contain no protein, only carbohydrates.','Eggs contain protein as well as other nutrients.','鸡蛋含有蛋白质；把它说成完全没有蛋白质是明确的营养事实错误。','meaning'),[Q(1,'Why might a runner eat beans as a source of protein?','Protein supplies material the body uses to build and repair tissue.','Protein is a type of protective eyewear.','Protein makes food contain no nutrients.','Protein is a nutrient used in growth and tissue repair.','meaning'),Q(2,'In a lab report, “a protein binds to the receptor” refers to…','a particular biological molecule','a serving of meat','a public trade policy','Sense 2 refers to an individual protein molecule.','context'),Q(1,'Which phrase is natural when discussing diet?','foods rich in protein','proteins of rainfall','a protein of a court session','Protein is commonly discussed as a nutrient in foods.','collocation'),Q(1,'A food label says 12 g protein per serving. What is being measured?','the amount of this nutrient in one serving','the food’s total number of cells','the serving’s temperature','Protein is a nutrient component whose mass can be listed on food labels.','meaning')]);
P('protest','From Latin protestari “declare publicly, testify,” from pro- “forth” + testari “witness”; it can mean public objection, to object, or to assert something firmly.',[C('protest.s1','社会','The workers held a peaceful protest outside the factory.','工人在工厂外举行了一场和平抗议。','hold/stage a protest','名词：公开表示反对的行动或声明。','organized public objection.','社会'),C('protest.s2','社会','Residents protested against the plan to close the clinic.','居民抗议关闭诊所的计划。','protest against/about + issue','动词：公开反对某政策或决定。','residents object publicly to the plan.','社会'),C('protest.s3','书面','He protested that he had never seen the missing document.','他坚称自己从未见过那份失踪文件。','protest that + clause','正式动词：坚称某事属实，常带有他人怀疑或争议。','he firmly declares his innocence.','书面')],M('Residents protested the clinic’s closure by celebrating that it would close.','Residents protested the clinic’s closure by demanding that it remain open.','抗议关闭诊所的举动应表达反对并要求保留，而不是庆祝关闭。','meaning'),[Q(1,'A peaceful protest outside a factory is…','a public action showing disagreement','a court sentence against a worker','a celebration of a new product','Protest as a noun is public objection or dissent.','meaning'),Q(2,'Choose the usual construction: “Residents protested ___ the plan.”','against','at to','from between','Protest against is the common pattern for objecting to a plan.','grammar'),Q(3,'“She protested that she had paid” means she…','firmly asserted that she had paid','organized a march about the payment','refused to speak about payment','Protest that can mean state firmly, especially in response to doubt.','meaning'),Q(1,'Which is a verb use of protest in the public-objection sense?','The students protested the new rule.','The students held a protest.','The rule was a protest.','The first sentence uses protest as an action verb.','grammar')]);
P('Protestantism','From Protestant + -ism; Protestant arose during the Reformation, initially for those who protested a 1529 imperial decree; Protestantism is the Christian tradition stemming from the Reformation.',[C('Protestantism.s1','通用','The museum’s exhibit traces the spread of Protestantism during the Reformation.','博物馆的展览追溯了宗教改革时期新教的传播。','the history/spread of Protestantism','指源自宗教改革的新教基督教传统。','exhibit concerns movement’s historical development.','宗教'),C('Protestantism.s2','通用','The lecture compared different beliefs within Protestantism.','讲座比较了新教内部的不同信仰。','beliefs/practices of Protestantism','也可集体指新教教义和实践。','beliefs are examined across churches.','宗教')],M('Protestantism is the branch of Christianity that began with the medieval papacy centuries before the Reformation.','Protestantism is the Christian tradition that emerged from the Reformation.','把新教说成宗教改革之前数世纪形成与其历史起源相矛盾。','meaning'),[Q(1,'Protestantism is historically associated with which movement?','the Reformation','the Industrial Revolution','the founding of the Roman Empire','Protestantism emerged from the Christian Reformation.','meaning'),Q(2,'A scholar compares beliefs within Protestantism. Which sense is emphasized?','the doctrines and practices of Protestant churches','a single protest march','the name of one church building','The term can collectively refer to a tradition’s beliefs and practices.','context'),Q(1,'Which phrase is natural?','the history of Protestantism','the Protestantism a witness','Protestantism at a minute','The standard phrase is the history, spread, or beliefs of Protestantism.','collocation'),Q(1,'Which statement is accurate?','Protestantism is a Christian tradition rooted in the Reformation.','Protestantism is a type of protein.','Protestantism means a public demonstration about any issue.','The term names the religious tradition, not a nutrient or generic protest.','meaning')]);
P('protester','From protest + agent suffix -er; protest comes from Latin protestari “declare publicly.” A protester is someone who publicly objects.',C('protester.s1','政治','One protester carried a sign calling for safer streets.','一名抗议者举着标语，呼吁改善道路安全。','a protester against/at + issue','指通过集会、示威或公开表达反对的人。','person publicly demands a change.','政治'),M('The protester supported the policy and marched to demand that it remain unchanged.','The protester opposed the policy and marched to demand that it be changed.','支持并要求维持政策的人不是该语境中的 protester。','meaning'),[Q(1,'Who is a protester?','a person who publicly objects to something','a person who writes the law alone','the policy being debated','The suffix -er names the person who protests.','word-formation'),Q(1,'Which action is typical of a protester?','joining a demonstration against a decision','quietly approving the decision','signing a contract without reading it','A protester expresses public disagreement, often in a demonstration.','context'),Q(1,'A protester against a new tax is someone who…','opposes the tax publicly','collects the tax for the city','designed the tax form','The preposition against identifies the policy opposed.','meaning'),Q(1,'Choose the correct relationship.','protester = person; protest = act or expression','protester = policy; protest = person','protester = court; protest = sentence','The agent noun names the participant; protest names the objection or action.','distinction')]);
P('protocol','From Greek prōtokollon “first sheet glued to a manuscript,” via French; senses developed to official forms, diplomatic rules, procedures, and communication standards.',[C('protocol.s1','外交','The ambassador followed protocol when presenting her credentials.','大使递交国书时遵守了礼仪程序。','follow/observe diplomatic protocol','名词，指正式场合的礼仪和行为规则。','presentation follows official etiquette.','外交'),C('protocol.s2','法律','The two countries signed a protocol on border inspections.','两国签署了一份关于边境检查的议定书。','sign/adopt a protocol','指附加于条约或协议的正式文件。','governments sign a written instrument.','法律'),C('protocol.s3','科技','The lab followed a safety protocol before handling the samples.','实验室在处理样本前遵循了一套安全规程。','follow a protocol; protocol for + procedure','指实验、医疗等活动规定的步骤；也可指计算机通信规则。','fixed steps guide lab procedure.','科技')],M('The laboratory ignored its protocol but claimed it had followed every required step.','The laboratory followed its protocol and completed every required step.','忽视流程与遵循流程相反，不能同时作为同一事实陈述。','meaning'),[Q(1,'Diplomatic protocol governs…','formal behavior at official events','the chemical formula of a sample','how a novel ends','The first sense is etiquette and formal procedure in diplomacy.','meaning'),Q(2,'A protocol signed by two countries is most likely…','a formal written agreement or supplement to a treaty','a person who negotiates','a casual greeting','Sense 2 is a written diplomatic/legal instrument.','context'),Q(3,'A lab safety protocol is…','a prescribed set of steps to follow','a list of guests at a dinner','a prediction of the experiment’s outcome','Sense 3 is an established procedure for an experiment or safety task.','meaning'),Q(3,'Which phrase is natural?','follow a protocol','prosecute a protocol to a guest','prostrate the protocol quickly','Procedures are followed; protocol itself is not a person or a legal defendant.','collocation')]);
P('proton','From Greek prōton, neuter of prōtos “first,” coined by Ernest Rutherford for the positively charged nuclear particle; in chemistry, a proton is also the hydrogen nucleus transferred in acid-base reactions.',[C('proton.s1','通用','A proton has a positive electric charge inside an atom.','质子是原子内部带正电的粒子。','proton has/carries a positive charge','粒子物理中的亚原子粒子。','positive charge defines the particle.','物理'),C('proton.s2','通用','In this reaction, the acid donates a proton to the base.','在这个反应中，酸向碱提供一个质子。','donate/accept a proton','化学中常将酸碱反应描述为质子的转移。','acid transfers H+ to base.','化学')],M('An electron has a positive charge and is found in the atomic nucleus.','A proton has a positive charge and is found in the atomic nucleus.','带正电并位于原子核的是质子；电子带负电，通常分布在核外。','confusable'),[Q(1,'What electric charge does a proton have?','positive','negative','zero in every context','A proton is positively charged.','meaning'),Q(2,'In acid-base chemistry, an acid donating a proton is…','transferring a hydrogen ion to a base','losing an electron to a proton','producing a neutron by splitting a molecule','A proton can be transferred as H+ in an acid-base reaction.','context'),Q(1,'Which particle contrasts with a proton by carrying a negative charge?','electron','neutron','photon','An electron is negatively charged, while a proton is positive.','distinction'),Q(1,'Where is a proton normally found in an atom?','in the nucleus','in the outer electron cloud','outside the atom with no relation to it','Protons are constituents of the atomic nucleus.','meaning')]);
P('protoplasm','From German Protoplasma, coined from Greek prōtos “first” + plasma “something formed”; a historical biological term for the living material within a cell.',C('protoplasm.s1','生物','The nineteenth-century text described protoplasm as the living material inside a cell.','这部十九世纪文本把原生质描述为细胞内的活性物质。','cellular protoplasm','旧式/历史生物学术语，指细胞膜内的活物质，具体用法随理论演变。','historical biological description.','生物'),M('The text called the cell wall, which is nonliving, the cell’s protoplasm.','The text called the living contents within the cell membrane its protoplasm.','原生质指细胞内活的物质，不是细胞外壁这一结构。','meaning'),[Q(1,'In older biology, protoplasm refers to…','the living material within a cell','the empty space between two organisms','a mineral deposit outside a cell','The term historically named the living contents of a cell.','meaning'),Q(1,'Which phrase fits the term?','the protoplasm of a cell','the protoplasm of a mountain range','a protoplasm of public law','The word belongs to biology and is used of cell contents.','collocation'),Q(1,'Why might a modern biology book use protoplasm cautiously?','It is a historical broad term whose scope changed with cell theory.','It means a newly discovered planet.','It is the standard name for a cell wall.','The term has a historical scientific usage and is less precise than modern subcellular terms.','context'),Q(1,'Which statement is most accurate?','Protoplasm is a historical term for living cellular material.','Protoplasm is the same as a proton.','Protoplasm is a kind of diplomatic protocol.','The biological word is distinct from proton and protocol.','distinction')]);
P('prototype','From Greek prōtotypon “first model,” from prōtos “first” + typos “impression, model”; it means an early working model or an original example.',[C('prototype.s1','工程','The engineers tested a prototype before manufacturing the final device.','工程师在制造最终设备前测试了一个原型。','build/test a prototype','指供测试或后续复制的初版样机、模型。','the device is tested before mass production.','工程'),C('prototype.s2','书面','The small village became a prototype for community-led planning.','这个小村庄成为社区主导规划的典型范例。','a prototype for/of + model','引申为后来同类事物所仿效的典型或雏形。','others may copy the model.','书面')],M('The prototype was the final mass-produced version, made after testing ended.','The prototype was an early model tested before mass production.','prototype 是早期模型或原型，不是已经量产的最终版本。','distinction'),[Q(1,'Why build a prototype of a new device?','to test an early model before full production','to replace all user instructions','to prove the device is already obsolete','A prototype is an initial model used to test and refine a design.','meaning'),Q(2,'A town is called a prototype for green planning. It is…','an example that later plans may imitate','a town that was built before all other towns','a machine used to measure carbon','The figurative sense is an original or typical model for later examples.','meaning'),Q(1,'Which phrase is natural?','a working prototype','a prototype yesterday','prototype the final product into a noun','A working prototype is an early functional model.','collocation'),Q(1,'A prototype fails a stress test. What does the result help engineers do?','revise the design before production','declare that no testing was performed','identify the company’s customers','Prototype testing reveals problems while the model can still be changed.','context')]);
P('prototypical','From prototype + -ical; prototype comes from Greek prōtotypon, “first model.” Prototypical means representing the most typical or exemplary form.',C('prototypical.s1','学术','A red apple is a prototypical example of the fruit in the children’s exercise.','在儿童练习中，红苹果是这种水果的典型范例。','prototypical example/case','形容某事物集中体现一类事物的典型特征。','example represents a familiar category member.','学术'),M('A prototypical triangle has four sides and one right angle.','A prototypical triangle has three sides.','三角形的典型定义是三条边；四边形不可能是其 prototypical example。','meaning'),[Q(1,'A prototypical example of a category is…','a representative or especially typical member','a member that cannot belong to it','an unrelated example chosen at random','Prototypical describes a clear, representative instance.','meaning'),Q(1,'Which phrase is idiomatic?','a prototypical case','a prototypical loudly','a prototypical of yesterday','The adjective commonly modifies example, case, or feature.','collocation'),Q(1,'If a robin is called a prototypical bird in a lesson, what is meant?','it is a familiar, representative bird example','it is the first bird ever to exist','it is not a bird','Prototypical means typical or exemplary, not literally the first historical specimen.','context'),Q(1,'Choose the best contrast for prototypical.','atypical','representative','classic','Atypical means not typical, the opposite of prototypical.','distinction')]);
P('protract','From Latin protrahere “draw forth, prolong,” from pro- “forth” + trahere “draw”; the verb means make something last longer, often unnecessarily.',[C('protract.s1','通用','Repeated objections protracted the meeting well past midnight.','反复的反对意见使会议拖到午夜以后才结束。','protract a meeting/delay/argument','及物，延长过程或使其拖沓；常带负面语气。','objections extend meeting duration.','通用'),C('protract.s2','通用','The constant uncertainty protracted the family’s suffering.','持续的不确定让这家人的痛苦一直延续。','protract suffering/conflict','可用于痛苦、冲突等被拖长的状态。','uncertainty lengthens suffering.','通用')],M('The quick settlement protracted the dispute by ending it immediately.','The quick settlement ended the dispute immediately.','迅速解决并立即结束争端不是“拖长”争端，protracted 与事实相反。','meaning'),[Q(1,'A protracted meeting is one that…','lasts longer than expected or needed','ends before it begins','takes place only outdoors','Protracted means prolonged or drawn out.','meaning'),Q(2,'What does it mean to protract suffering?','make it continue for longer','remove it instantly','measure it in meters','Sense 2 applies the verb to an extended period of suffering.','meaning'),Q(1,'Which verb is closest to protract in “protract the negotiations”?','prolong','conclude','summarize','To protract is to draw out or extend in time.','meaning'),Q(1,'The parties settled quickly to avoid protracting the conflict. What did they want to avoid?','making the conflict last longer','making the conflict easier to understand','measuring the conflict’s cost','The sentence uses protract as “prolong.”','context')]);
P('protrude','From Latin protrudere “thrust forward,” from pro- “forward” + trudere “push”; to protrude is to stick out beyond a surface.',C('protrude.s1','通用','A broken nail began to protrude through the old wooden board.','一颗断钉开始从旧木板上凸出来。','protrude from/through/beyond','不及物动词，描述物体伸出或突出。','nail extends beyond the board’s surface.','通用'),M('The nail protruded into the board and remained completely below its surface.','The nail protruded from the board and remained exposed.','若物体完全在表面下方，就没有 protrude（突出/伸出）。','meaning'),[Q(1,'If a branch protrudes from a wall, it…','sticks out beyond the wall’s surface','is painted onto the wall','has fallen behind the wall','Protrude means extend outward or project beyond a surface.','meaning'),Q(1,'Which preposition fits? “A cable protruded ___ the ceiling.”','through','despite','toward of','Protrude through a surface describes something emerging through it.','collocation'),Q(1,'Which object could protrude from a pocket?','the end of a pen','a sound that has no physical form','a calendar date','A pen can physically stick out of a pocket.','context'),Q(1,'What is a protruding handle doing?','extending outward from the object','folding inward and disappearing','being translated into another language','Protruding describes a part that projects outward.','meaning')]);
P('protrusion','From protrude + -ion; protrude comes from Latin protrudere “thrust forward.” A protrusion is a part that projects outward or the condition of doing so.',C('protrusion.s1','通用','The roof’s small protrusion sheltered the door from rain.','屋顶伸出的一小段为门口挡住了雨水。','a protrusion from/on a surface','可指突出物或突出的状态。','roof section projects over the doorway.','通用'),M('The flat panel had no protrusion, but a large knob stuck out from its center.','The flat panel had a protrusion: a large knob sticking out from its center.','明显伸出的旋钮就是 protrusion，不能同时说没有突出部。','meaning'),[Q(1,'A protrusion on a surface is…','a part that sticks out','a hole that goes all the way through','a flat color with no shape','A protrusion is an outward-projecting part or feature.','meaning'),Q(1,'Which phrase uses protrusion naturally?','a bony protrusion near the shoulder','a protrusion of yesterday','protrusion to be quietly','The noun can describe a physical feature that projects from a body or object.','collocation'),Q(1,'If a helmet has a protrusion, what should you look for?','a raised or projecting part','a hidden sentence in a book','a legal case against the helmet','The term refers to something sticking out from a surface.','context'),Q(1,'How are protrude and protrusion related?','protrude is the verb; protrusion is the noun','protrude is an adjective; protrusion is a verb','they have unrelated meanings','The -ion noun names the act or result of protruding.','word-formation')]);
P('proud','From Old English prūd, borrowed from Old French prud “brave, valiant,” later “having a high opinion”; proud can express justified satisfaction or excessive self-importance.',C('proud.s1','性格','She was proud of her team for finishing the bridge safely.','她为团队安全完成桥梁工程感到自豪。','proud of + person/achievement','形容词，表示因成就或亲近的人而感到满足、自豪。','team achievement is the source of pride.','通用'),M('He was proud for his daughter’s graduation and congratulated her.','He was proud of his daughter’s graduation and congratulated her.','表示因某人成就而自豪通常用 proud of，而非 proud for。','collocation'),[Q(1,'If someone is proud of a careful piece of work, they feel…','pleased and satisfied with what they achieved','ashamed that it exists','unaware of who made it','Proud of an achievement expresses satisfaction or self-respect.','meaning'),Q(1,'Complete: “The coach was proud ___ the players.”','of','at to','between','The usual construction is proud of someone or something.','collocation'),Q(1,'Which sentence suggests excessive self-importance rather than earned satisfaction?','He was too proud to admit any mistake.','She was proud of the volunteers’ effort.','They felt proud after finishing the rescue.','Too proud to admit a mistake suggests arrogance or excessive self-regard.','distinction'),Q(1,'A student is proud of improving her reading score. Why?','She is pleased with her achievement.','She is angry about being praised.','She has forgotten the result.','Proud can describe satisfaction in one’s own accomplishment.','context')]);
P('proudly','From proud + -ly; proud comes through Old French prud, “brave,” and now often means satisfied or dignified. Proudly is the corresponding adverb.',C('proudly.s1','通用','The graduates proudly displayed the certificates they had earned.','毕业生自豪地展示了自己获得的证书。','speak/show/walk proudly','副词修饰动作，表示以自豪或得意的方式。','displaying achievement with pride.','通用'),M('She proudly hid her award because she was ashamed to have received it.','She reluctantly hid her award because she was ashamed to have received it.','自豪地展示与因羞愧而隐藏相冲突，reluctantly 更符合后半句。','meaning'),[Q(1,'In “He proudly showed the repaired clock,” how did he show it?','with satisfaction in his achievement','without knowing it was there','because he wanted to damage it','Proudly describes an action done with pride or satisfaction.','meaning'),Q(1,'Which word does proudly modify in “They proudly sang the anthem”?','sang','they','anthem','Proudly is an adverb modifying the verb sang.','grammar'),Q(1,'Which situation fits “proudly announced”?','sharing good news with a sense of achievement','whispering because of deep embarrassment','accidentally deleting a message','Proudly signals satisfaction or dignity in making the announcement.','context'),Q(1,'Choose the adverb related to proud.','proudly','pridefuly','prouderly','The standard spelling adds -ly to proud: proudly.','spelling')]);
P('prove','From Old French prover, from Latin probare “test, approve”; the verb means establish truth, turn out to be, or demonstrate one’s ability.',[C('prove.s1','通用','The photographs helped prove that the package had arrived damaged.','这些照片有助于证明包裹送达时已经损坏。','prove that + clause; prove something','用证据或论证说明某事为真。','photographs serve as evidence.','通用'),C('prove.s2','通用','The shortcut proved slower than the main road.','结果发现，这条近路比主路更慢。','prove + adjective/noun; prove to be','表示后来发现具有某种性质或结果。','later experience reveals its quality.','通用'),C('prove.s3','通用','She wanted to prove herself as a reliable team leader.','她希望证明自己能胜任可靠的团队领导。','prove oneself','展示自己的能力、勇气或价值。','she demonstrates her ability in a role.','通用')],M('The photo proved that the parcel was intact, but it clearly showed the box crushed open.','The photo proved that the parcel was damaged; the box was visibly crushed open.','照片若清楚显示箱子被压坏，便不能证明包裹完好无损。','meaning'),[Q(1,'What does evidence do when it proves a claim?','shows that the claim is true','makes the claim impossible to test','changes the claim into a question','Prove in sense 1 means establish something as true using evidence or reasoning.','meaning'),Q(2,'“The simple repair proved expensive” means it…','turned out to be expensive','was proven by a judge to be cheap','proved someone’s ability','Prove + adjective can mean turn out to have a quality.','meaning'),Q(3,'To prove yourself at a new job is to…','demonstrate that you can do the work well','prove that you own the building','file a case against your manager','Prove oneself means show one’s ability or worth.','context'),Q(1,'Which form is grammatically correct?','The test proved that the material was safe.','The test proved the material be safe.','The test prove that material was safe yesterday.','Prove can take a that-clause stating what the evidence establishes.','grammar')]);
P('provenance','From French provenir “to come forth,” from Latin provenire “come from”; provenance is the origin of an object and often the record of its ownership history.',C('provenance.s1','艺术','The gallery checked the painting’s provenance before putting it up for auction.','画廊在拍卖前核查了这幅画的来源与流传记录。','the provenance of an artwork/object','指物品的来源，有时特指其历任所有者的可追溯记录。','gallery verifies origin and ownership chain.','艺术'),M('The painting’s provenance was its bright red color and three-meter width.','The painting’s provenance was its documented origin and chain of ownership.','颜色和尺寸是物品属性，不是 provenance；该词关乎来源和流传历史。','distinction'),[Q(1,'Why is an artwork’s provenance important?','It documents where it came from and who owned it.','It lists only the paint colors.','It proves how large the gallery is.','Provenance concerns an object’s origin and often its ownership history.','meaning'),Q(1,'Which phrase is natural?','the provenance of the manuscript','the provenance through a loud noise','the provenance to walk quickly','The usual construction is provenance of an object or work.','collocation'),Q(1,'A museum cannot establish a vase’s provenance. What is uncertain?','its origin or ownership history','its current color','the number of letters in its label','Provenance tracks where an object came from and how it changed hands.','context'),Q(1,'A receipt and old catalogue help establish an artifact’s…','provenance','proportion','propulsion','Records can support the artifact’s origin and chain of ownership.','meaning')]);
P('proverb','From Latin proverbium, from pro- “forth” + verbum “word”; a proverb is a short traditional saying that expresses common wisdom or truth.',[C('proverb.s1','语言','The proverb “Look before you leap” advises people to consider risks first.','“三思而后行”这句谚语劝人先考虑风险。','a proverb says/teaches that','传统简短语句，用来表达普遍经验、劝告或真理。','the saying offers practical advice.','语言'),C('proverb.s2','书面','She became the proverb of patience in the office, always waiting calmly.','她成了办公室里耐心的典型，总是平静地等待。','the proverb of + quality','较少见的引申用法，把某人或事当作某种特征的典型。','person is used as a familiar exemplar.','书面')],M('“Look before you leap” is a 40-page legal agreement, not a proverb.','“Look before you leap” is a short traditional proverb.','这是一句简短、流传的劝告，并非长篇法律文件。','distinction'),[Q(1,'What is a proverb?','a short traditional saying that expresses wisdom','a long list of ingredients','a person who prosecutes a case','A proverb is a compact, familiar saying that conveys a general truth or advice.','meaning'),Q(1,'Which is a proverb?','“Actions speak louder than words.”','“Please submit the form by noon.”','“The meeting is in room 4.”','The first is a traditional generalized saying; the others are instructions or facts.','context'),Q(2,'“He was the proverb of patience” presents him as…','a typical example of patience','the author of a law','someone who speaks only in verse','The less common sense treats a person or thing as a proverbial example.','meaning'),Q(1,'Which feature often makes a proverb memorable?','its brief, general advice or observation','its exact page number','its lack of any message','Proverbs are short and carry a widely applicable observation or lesson.','meaning')]);
P('provide','From Latin providere “foresee, prepare,” via Old French; the verb means supply, support/prepare for needs, or stipulate in a legal text.',[C('provide.s1','通用','The clinic provides clean water to every patient.','诊所为每位病人提供干净的饮用水。','provide something to/for someone','及物，供给所需物品、服务或信息。','clinic supplies a needed resource.','通用'),C('provide.s2','生活','He works two jobs to provide for his family.','他做两份工作来养家。','provide for a family; provide for future needs','表示供养某人或为未来需要作准备。','income supports dependents.','生活'),C('provide.s3','法律','The agreement provides that either party may cancel with notice.','协议规定，任何一方均可提前通知后取消。','provide that + clause','法律义项指文件明文规定。','clause states a rule.','法律')],M('The agreement provides to either party may cancel whenever they wish.','The agreement provides that either party may cancel with notice.','法律文件中表示“规定”时用 provide that + 从句；provide to 不能这样引导条款。','grammar'),[Q(1,'What does the clinic provide in the example?','clean water for patients','a court verdict against patients','a future prediction','Provide means give or supply something that is needed.','meaning'),Q(2,'If Ana works to provide for her family, she works to…','support them with necessities and money','offer them an argument to prove','write a legal clause about them','Provide for someone means supply their needs or support them.','meaning'),Q(3,'“The contract provides that payment is due in May” means the contract…','states this as a rule','supplies May as a product','asks the parties to propose a new contract','In legal style, provide that means stipulate or state a condition.','context'),Q(1,'Which pattern is correct when naming the recipient?','provide assistance to the residents','provide to assistance the residents','provide assistance at the residents','Provide assistance to someone is a standard construction.','grammar')]);
P('provide for','From provide + for; provide comes from Latin providere “foresee, prepare.” The phrasal verb means support someone or make arrangements for a possible future need.',[C('provide for.s1','家庭','She took a second job to provide for her children.','她又找了一份工作来供养孩子。','provide for + dependent','指提供生活所需、供养家庭成员。','earnings support dependents.','家庭'),C('provide for.s2','通用','The emergency plan provides for a backup power source.','应急计划为备用电源作了安排。','provide for + possibility/need','指预先安排或考虑某种未来需要。','plan anticipates a contingency.','通用')],M('The parent provided for the children by refusing them food and shelter.','The parent provided for the children by securing food and shelter.','供养孩子意味着满足其基本生活需要，拒绝食物和住所与此相反。','meaning'),[Q(1,'A parent works to provide for two children. What is the aim?','to support their needs','to submit them as a legal proposal','to prevent them from having any needs','Provide for a dependent means support that person’s needs.','meaning'),Q(2,'An insurance policy provides for flood damage. It…','includes arrangements or coverage for that possibility','causes the flood','supplies water to the flood','Provide for can mean make provision in advance for a possible event.','context'),Q(1,'Which use is correct?','The budget provides for repairs next year.','The budget provides for repaired loudly.','The budget provides the future by of repairs.','Provide for a future need means include arrangements for it.','grammar'),Q(1,'Which sentence means “support a household financially”?','He works nights to provide for his family.','He provides a report to the family.','He provides for the meeting’s agenda.','The first uses provide for with a dependent family.','distinction')]);
P('provided','From provide + past participle -ed; as a conjunction, provided (that) means “on the condition that”; as an adjective it can mean supplied.',[C('provided.s1','通用','You may borrow the camera, provided that you return it by Friday.','只要你在周五前归还，就可以借这台相机。','provided (that) + clause','连词，表示某条件必须满足，近似 on condition that。','borrowing depends on returning it.','通用'),C('provided.s2','通用','The provided meals were suitable for guests with allergies.','所提供的餐食适合有过敏症的客人。','provided + noun','过去分词形容词，表示已提供、备好的。','meals have been supplied.','通用')],M('You may enter provided you do not show your ticket at the door.','You may enter provided you show your ticket at the door.','provided 引出准入条件；不出示门票与获准进入相矛盾。','meaning'),[Q(1,'“You can join, provided that you register” means…','you can join only if you register','registration is forbidden','you may join without any condition','Provided that introduces a necessary condition.','meaning'),Q(2,'In “the provided materials,” provided means…','materials that have been supplied','materials that are impossible to find','materials that supplied the reader','As an adjective, provided means furnished or supplied.','grammar'),Q(1,'Which phrase is equivalent to “provided that”?','on condition that','because of yesterday','in contrast with','Provided that marks a condition.','distinction'),Q(1,'Choose the correct punctuation-free pattern: “We will go, provided ___ the road is open.”','that','what','whose','Provided that is followed by a clause giving the condition.','grammar')]);
P('providence','From Latin providentia “foresight,” from providere “foresee”; it can mean divine guidance or prudent foresight and care.',[C('providence.s1','宗教','The settlers believed providence had guided them safely through the storm.','定居者相信是天意引导他们安全度过了风暴。','divine Providence/providence','宗教义指上帝或神意对事件的引导、照料。','they attribute safe outcome to divine guidance.','宗教'),C('providence.s1','通用','Through providence, she had saved enough to repair the roof before winter.','幸而她早有远虑，攒下了足够的钱在冬天前修好屋顶。','remarkable providence/foresight','也可指谨慎的远见和提前准备。','prior saving anticipates a future need.','通用')],M('His providence meant he spent every coin immediately and had nothing for the winter.','His lack of providence meant he spent every coin immediately and had nothing for the winter.','providence 的非宗教义是远虑与提前准备；挥霍殆尽体现缺乏远虑。','meaning'),[Q(1,'In a religious account, providence may refer to…','divine guidance or care','a type of legal prosecutor','a measured proportion','The religious sense is protective guidance attributed to God or a divine force.','meaning'),Q(1,'Her providence led her to save emergency money. What does providence mean here?','foresight and prudent preparation','a sudden public protest','an unplanned expense','The nonreligious sense is practical foresight and care.','context'),Q(1,'Which phrase is natural?','trust in divine providence','providence under a spoon','a providence of three meters','Divine providence is the established religious collocation.','collocation'),Q(1,'Someone who plans for winter before the first frost shows…','providence','procrastination','prosecution','Advance preparation shows foresight, one sense of providence.','meaning')]);
P('provident','From Latin providens, present participle of providere “foresee”; provident describes planning ahead and, by extension, careful use of money.',[C('provident.s1','通用','A provident household keeps an emergency fund for unexpected repairs.','有远见的家庭会留出应急金，用于意外维修。','provident planning/person','形容词，表示考虑未来并提前作好准备。','emergency fund anticipates future expense.','通用'),C('provident.s2','通用','Her provident habits helped her avoid debt during a slow season.','她节俭持家的习惯帮助她在淡季避免了负债。','provident with money/resources','也指节俭、善于谨慎管理钱财。','careful spending protects against debt.','通用')],M('The provident planner ignored every warning and spent the emergency fund on luxuries.','The imprudent planner ignored every warning and spent the emergency fund on luxuries.','无视风险并花光应急金不是 provident（有远见、谨慎）的做法。','meaning'),[Q(1,'A provident person prepares for…','future needs and possible difficulties','only events that have already ended','a debate they will never attend','Provident means prudent and forward-looking.','meaning'),Q(2,'A provident saver is likely to…','manage money carefully and avoid waste','spend all savings impulsively','refuse to plan for any bills','The second sense emphasizes thrift and careful resource management.','context'),Q(1,'Which action is most provident?','saving part of each paycheck for emergencies','borrowing for every minor purchase','ignoring an upcoming tax bill','Planning and saving ahead show providence and provident judgment.','context'),Q(1,'Which word is closest in meaning to provident?','prudent','careless','profligate','Provident describes prudent foresight; careless and profligate are opposites.','distinction')]);
P('province','From Latin provincia, a Roman sphere of duty or territory, through Old French; it means an administrative region or a person’s proper field.',[C('province.s1','地理','Quebec is a province of Canada with its own elected assembly.','魁北克是加拿大的一个省，设有自己的民选议会。','a province of + country','在某些国家指一级行政区。','region is part of a country.','地理'),C('province.s2','书面','Solving tax disputes is outside the province of this committee.','解决税务争议不属于该委员会的职责范围。','within/outside the province of + person/field','比喻某人或机构的职责、知识或活动范围。','committee lacks jurisdiction over tax matters.','书面')],M('Quebec is a province of the Pacific Ocean, not part of Canada.','Quebec is a province of Canada, not part of the Pacific Ocean.','魁北克是加拿大的行政区，并非海洋的一部分。','meaning'),[Q(1,'A province of a country is…','a main administrative region','a type of legal objection','a single elected person','Province in the geographic sense is a territorial unit within some countries.','meaning'),Q(2,'“The issue is outside my province” means it is…','outside my area of responsibility or expertise','outside my country’s borders','inside my house','The figurative sense is one’s proper field, responsibility, or expertise.','meaning'),Q(1,'Which phrase is standard?','the province of Ontario','the province to a problem','a province by a question','A province is usually named as a province of a country or territory.','collocation'),Q(2,'A doctor says a legal contract is not her province. What is she saying?','It is outside her professional field.','It is her home province.','She has signed the contract.','Province can figuratively mean a person’s area of knowledge or responsibility.','context')]);
P('provincialism','From provincial + -ism; provincial derives from Latin provincia. Provincialism can mean narrow local-mindedness or a regional custom, word, or manner.',C('provincialism.s1','社会','The essay warned that provincialism can make a community dismiss unfamiliar ideas.','这篇文章警告说，地方狭隘观念会让社群轻视陌生想法。','cultural/intellectual provincialism','常指视野局限于本地、排斥外界的态度；也可指地方用语或习惯。','insularity dismisses outside ideas.','社会'),M('Her provincialism meant she eagerly studied customs from many cultures and welcomed new ideas.','Her openness to other cultures meant she studied their customs and welcomed new ideas.','开放接纳外来观点与 provincialism 的狭隘、地方本位态度相反。','distinction'),[Q(1,'A person criticized for provincialism may…','dismiss ideas simply because they come from elsewhere','welcome all unfamiliar perspectives','have moved to a different province','Provincialism can mean narrowness of outlook tied to one’s own region.','meaning'),Q(1,'Which phrase is natural?','intellectual provincialism','provincialism quickly a table','provincialism of three liters','The noun commonly describes a narrow intellectual or cultural outlook.','collocation'),Q(1,'A dictionary may label a local word a provincialism. What does that mean?','a regional expression or usage','a legal contract clause','a universal scientific unit','The word also names a regional term, habit, or expression.','meaning'),Q(1,'Which behavior best avoids provincialism?','listening seriously to ideas from other cultures','rejecting every custom beyond one’s hometown','assuming local practice is always best','Provincialism is narrow local-mindedness; openness counters it.','context')]);
P('provision','From Latin provisio “foresight, preparation,” from providere “foresee”; it denotes a supply or a clause/rule in a law or agreement.',[C('provision.s1','法律','The contract includes a provision allowing either party to end the lease with notice.','合同包含一项条款，允许任何一方提前通知后终止租约。','a provision in a contract/law','名词，指法律或合同中的具体规定。','clause sets a legal condition.','法律'),C('provision.s2','通用','The crew checked its provision of fresh water before leaving port.','船员在离港前检查了淡水储备。','provision of + supply/service','指提供或储备的物资、供给；也可表示供给行为。','water is a necessary supply.','通用')],M('A provision in the contract supplied fresh water to the crew, and every barrel was a legal clause.','A provision in the contract required the company to supply fresh water to the crew.','法律条款可以规定供水义务；水桶本身不是合同条款。','distinction'),[Q(1,'A provision in a contract is…','a specific clause or rule','a person who owns the contract','a view over a harbor','The legal sense is a statement included in an agreement or law.','meaning'),Q(2,'A ship carries provisions for a long voyage. These are…','supplies, especially food or necessities','written contract clauses','people who prosecute a case','Provision can mean necessary supplies or stores.','meaning'),Q(1,'Which phrase uses the legal sense?','a provision of the lease','a provision of biscuits on the table','provision a ship across the bay','A provision of a lease is a contractual clause.','context'),Q(1,'Which phrase refers to supplies?','provision of emergency food','a provision allowing appeals','a provision in the statute','Emergency food is a supply; the latter phrases name legal clauses.','distinction')]);
P('provisional','From provision + -al; provision comes from Latin provisio “foresight, preparation.” Provisional means arranged temporarily until a final decision.',C('provisional.s1','通用','The committee issued a provisional schedule that may change after room assignments.','委员会发布了一份临时日程，房间安排确定后仍可能变动。','provisional agreement/result/plan','形容尚未最终确定、以后可能修改的安排或结论。','schedule awaits final room assignment.','通用'),M('The provisional schedule was final and could never be changed.','The provisional schedule was temporary and could still be changed.','provisional 明确表示暂定；“final and never changed”与之矛盾。','meaning'),[Q(1,'A provisional result is…','temporary and subject to confirmation','final and impossible to revise','a result about a province only','Provisional means arranged for the present but not yet final.','meaning'),Q(1,'Which phrase is natural?','provisional approval','provisional yesterday','provisional loudly','Approval can be provisional while further checks remain.','collocation'),Q(1,'A provisional road closure may be changed after inspection. Why provisional?','it is not yet final','it applies only to a province','it lasts forever with no review','The closure is temporary and may be revised after more information.','context'),Q(1,'Which contrasts with provisional?','permanent and final','temporary','tentative','Provisional is tentative; permanent and final provide the contrast.','distinction')]);
P('provisionally','From provisional + -ly; provisional is built on provision and expresses a temporary or not-yet-final status. Provisionally is its adverb.',C('provisionally.s1','通用','The board provisionally approved the design pending a safety review.','董事会暂时批准了设计，等待安全审查结果。','approve/appoint/accept provisionally','副词修饰决定或安排，表示尚待确认。','approval awaits a review.','通用'),M('The board provisionally approved the plan as final and barred any later review.','The board finally approved the plan and barred any later review.','尚待后续审查和不允许复核不相容；provisionally 不能表示最终批准。','meaning'),[Q(1,'If a person is appointed provisionally, the appointment is…','temporary or awaiting confirmation','permanent and beyond review','a method of measuring distance','Provisionally indicates a not-yet-final arrangement.','meaning'),Q(1,'Which sentence uses provisionally correctly?','The result was provisionally accepted until the audit finished.','The result provisionally the audit yesterday.','They provisionally accepted nothing because it was already final.','The adverb modifies accepted and signals later confirmation is pending.','grammar'),Q(1,'What may follow a provisional approval?','a review or final decision','a guarantee that no change is possible','a different part of speech','Provisionally means the decision can be reconsidered after a condition or review.','context'),Q(1,'Choose the closest paraphrase: “The route was provisionally selected.”','The route was selected for now, subject to confirmation.','The route was selected permanently after all reviews.','The route was rejected without discussion.','Provisionally means tentatively or for the present.','meaning')]);
P('provisions','From provision, ultimately Latin provisio “foresight, preparation”; the plural commonly means food and essential supplies kept for use.',C('provisions.s1','饮食','The hikers packed provisions for three days in the mountains.','徒步者带上了足够在山里生活三天的食物和必需品。','pack/carry provisions','复数名词，指旅行或困难时期储备的食物与物资。','supplies sustain a trip.','饮食'),M('The hikers packed provisions for three days but brought no food or supplies.','The hikers packed provisions—food and supplies—for three days.','若没带任何食物或物资，就不能说 packed provisions。','meaning'),[Q(1,'What are provisions for a mountain hike?','food and necessary supplies','the hike’s legal contract clauses','a person who guides a legislature','Provisions commonly means stores of food and essentials.','meaning'),Q(1,'Which verb commonly goes with provisions?','pack','prosecute','protrude','Travelers pack or carry provisions before a journey.','collocation'),Q(1,'A ship loads provisions before a long voyage. Why?','to have food and essentials available during the trip','to measure the ocean’s depth','to make the vessel heavier for no reason','Provisions are supplies kept for a journey or future need.','context'),Q(1,'In “The camp’s provisions ran low,” what ran low?','its stored food and supplies','its contract clauses','its crew’s legal authority','The plural noun refers to the camp’s stock of necessities.','meaning')]);
P('provocation','From provoke + -ation; provoke comes from Latin provocare “call forth.” Provocation is an act that incites anger or a reaction, or the cause of it.',C('provocation.s1','通用','The referee warned both players not to respond to provocation from the crowd.','裁判警告两名球员不要回应观众的挑衅。','respond to/without provocation','名词，指故意激怒人的言行或引发反应的事由。','crowd action tempts a reaction.','通用'),M('He punched the stranger without provocation, although the stranger had just attacked him.','He punched the stranger after the stranger attacked him.','对方先发动攻击构成挑衅或诱因，不能说毫无 provocation。','meaning'),[Q(1,'A deliberate provocation is meant to…','make someone angry or prompt a reaction','calm everyone without speaking','supply food for a trip','Provocation is behavior intended to incite anger or another response.','meaning'),Q(1,'Which phrase is natural?','without provocation','provocation for a sandwich','provocation under a calendar','The phrase without provocation means without being prompted or provoked.','collocation'),Q(1,'A crowd shouts insults to provoke a player. The insults are…','a provocation','a provision','a provenance','The insults are the act intended to cause an angry reaction.','context'),Q(1,'Which is closest in meaning to provocation?','incitement','protection','proportion','Provocation can mean an action that incites or stirs up a response.','meaning')]);
P('provocative','From provoke + -ative; provoke comes from Latin provocare “call forth.” Provocative describes something deliberately causing thought, anger, argument, or desire.',C('provocative.s1','通用','The columnist asked a provocative question about who benefits from the policy.','专栏作者提出了一个引发思考的问题：这项政策让谁受益？','provocative question/comment/art','形容有意激起强烈反应；可能是争议性的，也可能是挑逗性的。','question challenges readers to think.','通用'),M('The provocative remark was designed to avoid all discussion and leave no one thinking.','The provocative remark was designed to spark discussion and make readers think.','provocative 的作用是引起反应或思考，而非完全避免讨论。','meaning'),[Q(1,'A provocative question is one that…','is likely to stimulate thought or strong reaction','has no meaning and cannot be answered','is always a polite greeting','Provocative describes something that provokes thought, debate, or feeling.','meaning'),Q(1,'Which phrase is natural?','a provocative statement','a provocative silently','a provocative of two liters','The adjective commonly modifies question, statement, image, or behavior.','collocation'),Q(1,'A provocative artwork causes a heated debate. What does provocative emphasize?','its power to elicit a response','its exact physical dimensions','its legal owner’s name','The word refers to the reaction the artwork deliberately or readily evokes.','context'),Q(1,'Could provocative have a sexual sense?','Yes, it can describe something intended to arouse desire.','No, it can only mean legally forbidden.','Yes, but only when describing a measurement.','Provocative may describe behavior or clothing intended to arouse sexual interest.','meaning')]);
P('provoke','From Latin provocare “call forth, challenge,” from pro- “forth” + vocare “call”; the verb means deliberately anger someone or cause a reaction.',[C('provoke.s1','通用','The barking dog provoked the normally calm horse.','吠叫的狗激怒了那匹平时很温顺的马。','provoke someone into anger/action','使人或动物生气、起冲突或采取行动。','dog’s behavior triggers a reaction.','通用'),C('provoke.s2','通用','The proposal provoked serious questions about the project’s cost.','这项提案引发了人们对项目成本的严肃质疑。','provoke a response/reaction/debate','引起某种反应、情绪或讨论。','proposal causes questions.','通用')],M('The insult provoked him into staying perfectly calm and feeling no anger.','The insult provoked him into shouting angrily.','侮辱若使他保持平静，就没有引发愤怒；错误句前后语义相反。','meaning'),[Q(1,'If a remark provokes someone, it may…','make that person angry','protect that person from every reaction','provide that person with a legal title','Provoke in sense 1 means anger or incite someone.','meaning'),Q(2,'A question provokes debate. What does provoke mean there?','cause or stimulate debate','forbid anyone to speak','answer the debate completely','Sense 2 means bring about a response or discussion.','meaning'),Q(1,'Choose the natural pattern: “The taunt provoked her ___ replying.”','into','for to','by at','Provoke someone into doing something is a standard construction.','grammar'),Q(2,'Which event is most likely to provoke public concern?','a report revealing unsafe drinking water','a routine notice that the library opens at nine','a blank page with no information','A serious safety report can trigger public concern.','context')]);
P('prowess','From Old French prouesse “bravery, valor,” from prou “valiant”; prowess is exceptional skill, strength, or bravery in a particular activity.',C('prowess.s1','通用','The young goalkeeper showed remarkable prowess during the final match.','这位年轻守门员在决赛中展现出非凡的本领。','prowess in/at + activity','不可数名词；强调出色技能，旧义也含勇武。','goalkeeping skill is exceptional.','通用'),M('Her prowess at chess was proved by losing every game in one move.','Her lack of chess prowess was clear after she lost every game in one move.','连续一步败局说明缺乏棋艺，而不是高超的 prowess。','meaning'),[Q(1,'A musician’s prowess is…','exceptional skill in music','the musician’s monthly rent','a rule against playing music','Prowess means outstanding ability or skill.','meaning'),Q(1,'Which phrase is common?','athletic prowess','prowess into the drawer','prowess for yesterday','Prowess is often described by an activity or domain such as athletic or military.','collocation'),Q(1,'A commander praised for battlefield prowess is praised for…','skill and bravery in battle','careful spelling in a report','the size of the army’s tents','The historical sense includes bravery and military skill.','context'),Q(1,'Which person displays prowess?','a pianist who performs a difficult piece with great skill','a player who never practices and cannot perform','a spectator who missed the concert','Prowess is demonstrated by exceptional ability.','meaning')]);
P('prowl','From Middle English prollen, perhaps related to a Scandinavian word meaning creep; it means move stealthily while searching or hunting.',C('prowl.s1','通用','A fox prowled around the henhouse after dark.','天黑后，一只狐狸悄悄在鸡舍周围徘徊觅食。','prowl around/about; prowl for prey','动词，指为寻找猎物或机会而悄悄游荡。','fox moves stealthily while hunting.','通用'),M('The fox prowled loudly through the henhouse in broad daylight, announcing its arrival.','The fox crept quietly around the henhouse after dark.','悄悄潜行的 prowl 与大声宣告行踪相矛盾。','meaning'),[Q(1,'A cat prowling around the garden is…','moving stealthily while searching','sleeping in one fixed place','being carried openly by a person','Prowl means roam quietly or stealthily, often while hunting or seeking something.','meaning'),Q(1,'Which preposition commonly follows prowl?','around','between of','despite','Prowl around/about a place is a natural pattern.','collocation'),Q(1,'A burglar prowls a neighborhood at night. What is implied?','the burglar moves about quietly looking for an opportunity','the burglar is giving a daytime tour','the burglar has already been arrested','Prowl suggests secretive movement while looking for prey or an opportunity.','context'),Q(1,'Which is closest to prowl?','stalk','celebrate','propose','To prowl is to move stealthily, much like stalking.','meaning')]);
P('proximate','From Latin proximatus, past participle of proximare “come near,” from proximus “nearest”; it means nearest in time/space or directly causal.',[C('proximate.s1','书面','The clinic is the proximate building to the north entrance.','诊所是离北入口最近的建筑。','proximate to + place/time','正式形容词，表示时间或空间上最接近。','clinic is closest in space.','书面'),C('proximate.s2','法律','The investigators identified the proximate cause of the equipment failure.','调查人员确定了设备故障的直接原因。','proximate cause','法律或因果分析中，指直接而非遥远的原因。','cause is immediate in causal chain.','法律')],M('The proximate cause was a distant policy adopted centuries ago, with no immediate cause involved.','The proximate cause was the loose wire that directly triggered the failure.','proximate cause 指直接近因；遥远背景因素不属于直接原因。','distinction'),[Q(1,'The proximate building to a gate is…','the one nearest to it','the most expensive building','the building farthest away','Proximate means nearest in place or sequence.','meaning'),Q(2,'A proximate cause of a crash is…','the direct cause closest in the causal chain','the most remote historical influence','the driver’s favorite color','Sense 2 identifies the immediate or direct cause.','context'),Q(1,'Which phrase is natural?','proximate to the entrance','proximate under the entrance','proximate of a sentence','Proximate to is used to state what something is near.','grammar'),Q(2,'A report separates background conditions from the proximate cause. The latter is…','the immediate factor that triggered the event','every distant condition in history','a result that occurred years afterward','The proximate cause directly produces the event under analysis.','meaning')]);
P('proximity','From Latin proximitas “nearness,” from proximus “nearest”; proximity is closeness in location or, figuratively, in relationship.',[C('proximity.s1','通用','The school’s proximity to the train station makes commuting easy.','学校靠近火车站，因此通勤很方便。','proximity to + place','名词，指空间位置上的接近。','short distance benefits commuters.','通用'),C('proximity.s2','通用','Years of working together created a sense of emotional proximity.','多年共事让他们产生了情感上的亲近感。','emotional/close proximity','也可指人与人之间关系或感情的亲近。','shared experience creates closeness.','通用')],M('The station’s proximity to the school meant it was fifty kilometers away.','The station’s distance from the school meant it was fifty kilometers away.','proximity 表示接近，而五十公里的远距用 distance 更恰当。','meaning'),[Q(1,'A house in close proximity to a station is…','near the station','inside the station’s timetable','far from every transport link','Proximity means nearness in place.','meaning'),Q(2,'Emotional proximity between friends refers to…','closeness in their relationship','the distance between their houses only','their matching phone numbers','The figurative sense concerns relational or emotional closeness.','context'),Q(1,'Which preposition follows proximity in the common pattern?','to','of from','beneath at','Proximity to names the person or place something is near.','collocation'),Q(1,'A hospital is built in proximity to a highway. What practical benefit may follow?','easy access for patients and emergency vehicles','a guarantee that traffic cannot exist','the end of all medical services','Being near a highway may make transport access easier.','meaning')]);
})();
